Object.assign(window.TEM8_DICTIONARY, {"saloon":{"media":{"img":["media/pic/cars_photos_comp.jpg","media/thumb/saloon.jpg"],"uk":"media/uk/saloon__gb_1.mp3","us":"media/us/saloon__us_1.mp3"},"oxford":{"phon":"səˈluːn","pos":"noun","senses":[{"en":"a car with a boot (= space at the back for carrying things) that is separated from the part where the driver and passengers sit","cn":"小轿车；三厢轿车","lab":"both British English","ex":{"en":"a five-seater family saloon","cn":"五座家庭式轿车"}},{"en":"a bar in a pub, hotel, etc. that is more comfortable than the other bars and where the drinks are usually more expensive","cn":"（酒馆、旅馆等的）高级酒吧，豪华酒吧","lab":"all British English"},{"en":"a bar where alcoholic drinks were sold in the western US and Canada in the past","cn":"（旧时美国西部和加拿大的）酒吧，酒馆","ex":{"en":"The cowboy died in a fight in a saloon.","cn":"这个牛仔在酒馆的一次斗殴中丧生。"}},{"en":"a large comfortable room on a ship, used by the passengers to sit and relax in","cn":"（客轮上的）交谊厅","ex":{"en":"The saloon on deck B has room for 140 passengers.","cn":"B 甲板上的沙龙可容纳 140 名乘客。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(双排座)轿车，箱式小客车","en":"A saloon or a saloon car is a car with seats for four or more people, a fixed roof, and a boot that is separated from the rear seats."},{"pos":"N-COUNT 可数名词","cn":"酒吧;酒馆","en":"A saloon is a place where alcoholic drinks are sold and drunk."},{"pos":"N-COUNT 可数名词","cn":"酒吧雅座;(宾馆的)高级酒廊","en":"The saloon or saloon bar in a pub or hotel is a comfortable bar where the drinks are more expensive than in the other bars."}]},"examples":[{"en":"a five-seater family saloon","cn":"五座家庭式轿车"},{"en":"a four-door family saloon","cn":"四门家庭厢式轿车"}]},"safety":{"media":{"uk":"media/uk/safety__gb_1.mp3","us":"media/us/safety__us_1.mp3"},"oxford":{"phon":"ˈseɪfti","pos":"noun","senses":[{"en":"the state of being safe and protected from danger or harm","cn":"安全；平安","g":"[uncountable]","ex":{"en":"a place where children can play in safety","cn":"可以让儿童安全玩耍的地方"}},{"en":"the state of not being dangerous","cn":"安全性；无危险","g":"[uncountable]","ex":{"en":"I'm worried about the safety of the treatment.","cn":"我担心这种疗法是否安全。"}},{"en":"a place where you are safe","cn":"安全处所","g":"[uncountable]","ex":{"en":"They reached safety seconds before the building was engulfed in flames.","cn":"他们到达安全地几秒钟之后，那房子就成了一片火海。"}},{"en":"a device that stops a gun from being fired or a machine from working by accident","cn":"（枪、炮等的）保险机，保险栓；（机器设备的）安全掣子","g":"[countable]","lab":"North American English"},{"en":"(in American football) a defending player who plays in a position far away from the other team","cn":"（美式足球）安全卫，中卫","g":"[countable]","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"平安;安全","en":"Safety is the state of being safe from harm or danger.","ex":{"en":"The report goes on to make a number of recommendations to improve safety on aircraft.","cn":"该报告接着给出了一系列改善飞机安全性能的建议。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"安全场所;安全的地方","en":"If you reach safety, you reach a place where you are safe from danger.","ex":{"en":"He stumbled through smoke and fumes given off from her burning sofa to pull her to safety","cn":"她的沙发着火了，他冒着浓烟跌跌撞撞地把她拉到安全的地方。"}},{"pos":"N-SING 单数名词","cn":"安全程度;安全性;无害;无危险","en":"If you are concerned about the safety of something, you are concerned that it might be harmful or dangerous.","ex":{"en":"...consumers are showing growing concern about the safety of the food they buy","cn":"消费者越来越关注所购食品的安全性。"}},{"pos":"N-SING 单数名词","cn":"(某人的)安全","en":"If you are concerned for someone's safety, you are concerned that they might be in danger.","ex":{"en":"There is grave concern for the safety of witnesses","cn":"人们非常担心证人的安全。"}},{"pos":"ADJ 形容词","cn":"(特征、措施)保障安全的","en":"Safety features or measures are intended to make something less dangerous.","ex":{"en":"The built-in safety device compensates for a fall in water pressure.","cn":"该内置式安全装置在水压下降时能提供保护。"}},{"pos":"PHRASE 短语","cn":"人多保险;人多势众","en":"If you say that there is safety in numbers, you mean that you are safer doing something if there are a lot of people doing it rather than doing it alone.","ex":{"en":"Many people still feel there is safety in numbers when belonging to a union.","cn":"许多人仍然感到加入工会后会有强大的后盾。"}}]},"examples":[{"en":"The police are concerned for the safety of the 12-year-old boy who has been missing for three days.","cn":"那个 12 岁的男孩失踪三天了，警方对他的安全感到担忧。"},{"en":"They reached safety seconds before the building was engulfed in flames.","cn":"他们到达安全地几秒钟之后，那房子就成了一片火海。"}]},"satisfaction":{"media":{"uk":"media/uk/satisfaction__gb_1.mp3","us":"media/us/satisfaction__us_1.mp3"},"oxford":{"phon":"ˌsætɪsˈfækʃn","pos":"noun","senses":[{"en":"the good feeling that you have when you have achieved something or when something that you wanted to happen does happen; something that gives you this feeling","cn":"满足；满意；欣慰；令人满意（或欣慰）的事","g":"[uncountable, countable]","ex":{"en":"to gain/get/derive satisfaction from something","cn":"从某事中得到满足感"}},{"en":"the act of fulfilling a need or desire","cn":"（需要或欲望的）满足，达到","g":"[uncountable]","ex":{"en":"the satisfaction of sexual desires","cn":"性欲的满足"}},{"en":"an acceptable way of dealing with a complaint, a debt, an injury, etc.","cn":"（抗议、投诉等的）妥善处理；（债务的）清偿；（伤害的）赔偿","g":"[uncountable]","lab":"formal","ex":{"en":"I complained to the manager but I didn't get any satisfaction.","cn":"我向经理投诉，但问题丝毫没有得到解决。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"满意;满足;称心","en":"Satisfaction is the pleasure that you feel when you do something or get something that you wanted or needed to do or get.","ex":{"en":"She felt a small glow of satisfaction","cn":"她有了一丝满足感。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赔偿;补偿","en":"If you get satisfaction from someone, you get money or an apology from them because you have been treated badly.","ex":{"en":"If you can't get any satisfaction, complain to the park owner.","cn":"如果你得不到任何赔偿，向园区所有者投诉。"}},{"pos":"PHRASE 短语","cn":"令…满意","en":"If you do something to someone's satisfaction, they are happy with the way that you have done it.","ex":{"en":"She never could seem to do anything right or to his satisfaction","cn":"她似乎从没能做过一件正确或令他满意的事。"}}]},"examples":[{"en":"Can you demonstrate to our satisfaction that your story is true?","cn":"你能不能证实一下，让我们确信你说的是事实？"},{"en":"He had the satisfaction of seeing his book become a best-seller.","cn":"看到自己的作品成了畅销书，他志得意满。"}]},"saturday":{"media":{"uk":"media/uk/saturday__gb_1.mp3","us":"media/us/saturday__us_1.mp3"},"oxford":{"phon":"ˈsætədeɪ","pos":"noun","senses":[{"en":"the day of the week after Friday and before Sunday","cn":"星期六","lab":"informal or North American English","ex":{"en":"It's Saturday today, isn't it?","cn":"今天是星期六，对吧？"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"星期六","en":"Saturday is the day after Friday and before Sunday.","ex":{"en":"She had a call from him on Saturday morning at the studio","cn":"星期六早上她在录音室接到他打来的电话。"}}]}},"salad":{"oxford":{"phon":"ˈsæləd","pos":"noun","senses":[{"en":"a mixture of raw vegetables such as lettuce, tomato and cucumber, usually served with other food as part of a meal","cn":"（生吃的）蔬菜色拉，蔬菜沙拉","g":"[uncountable, countable]","lab":"British English","ex":{"en":"All main courses come with salad or vegetables.","cn":"所有主菜都配有色拉或蔬菜。"}},{"en":"meat, fish, cheese, etc. served with salad","cn":"（拌有肉、鱼、奶酪等的）混合色拉，混合沙拉","g":"[countable, uncountable]","ex":{"en":"a chicken/tuna/seafood/egg salad","cn":"鸡肉／金枪鱼／海鲜／鸡蛋色拉"}},{"en":"raw or cooked vegetables, etc. that are cut into small pieces, often mixed with mayonnaise and served cold with other food","cn":"（或生或熟，切丁，多拌有蛋黄酱，作配菜冷食的）色拉，沙拉","g":"[uncountable, countable]","ex":{"en":"potato salad","cn":"土豆色拉"}},{"en":"any green vegetable, especially lettuce, that is eaten raw in a salad","cn":"拌色拉的青菜（尤指生菜）","g":"[countable]","ex":{"en":"salad plants/leaves","cn":"色拉蔬菜／菜叶"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"色拉;凉拌菜","en":"A salad is a mixture of raw or cold foods such as lettuce, cucumber, and tomatoes. It is often served with other food as part of a meal.","ex":{"en":"...a salad of tomato, onion and cucumber.","cn":"西红柿、洋葱和黄瓜拌成的色拉"}},{"pos":"PHRASE 短语","cn":"少不更事时期;涉世未深的青少年时期","en":"If you refer to your salad days, you are referring to a period of your life when you were young and inexperienced.","ex":{"en":"The Grand Hotel did not seem to have changed since her salad days.","cn":"从她年少时候到现在，格兰德酒店似乎一直就没有变过。"}}]},"media":{"img":["media/ldoce/img/salad.jpg","media/pic/salad_vegetables_comp.jpg"],"uk":"media/uk/salad__gb_1.mp3","us":"media/us/salad__us_1.mp3"},"examples":[{"en":"All main courses come with salad or vegetables.","cn":"所有主菜都配有色拉或蔬菜。"},{"en":"a side salad (= a small bowl of salad served with the main course of a meal)","cn":"配菜色拉（作为一道副菜）"}]},"sadness":{"oxford":{"phon":"ˈsædnəs","pos":"noun","senses":[{"en":"the feeling of being sad","cn":"悲伤；悲痛；难过","g":"[uncountable, singular]","ex":{"en":"memories tinged with sadness","cn":"略带悲伤的往事"}},{"en":"something which makes you sad","cn":"使人悲伤（或难过）的事","g":"[countable, usually plural]","ex":{"en":"our joys and sadnesses","cn":"我们的欢乐和悲伤"}}]},"media":{"uk":"media/uk/sadness__gb_1.mp3","us":"media/us/sadness__us_1.mp3"},"examples":[{"en":"I felt a deep sadness.","cn":"我感到深深的悲痛。"},{"en":"our joys and sadnesses","cn":"我们的欢乐和悲伤"}]},"saying":{"media":{"uk":"media/uk/saying__gb_1.mp3","us":"media/us/saying__us_1.mp3"},"oxford":{"phon":"ˈseɪɪŋ","pos":"noun","senses":[{"en":"a well-known phrase or statement that expresses something about life that most people believe is wise and true","cn":"谚语；格言；警句","ex":{"en":"‘Accidents will happen’, as the saying goes.","cn":"常言道：“意外事，总难免。”"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"谚语;格言;警句","en":"A saying is a sentence that people often say and that gives advice or information about human life and experience.","ex":{"en":"We also realize the truth of that old saying: Charity begins at home","cn":"我们也明白了那句老话的道理：仁爱始于家庭。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指宗教或政治领袖的)重要讲话，教诲，名言","en":"The sayings of a person, especially a religious or political leader, are important things that they said or pieces of advice that they gave.","ex":{"en":"The sayings of Confucius offer guidance on this matter.","cn":"孔子的教诲为此事提供了指引。"}}]},"examples":[{"en":"‘Accidents will happen’, as the saying goes.","cn":"常言道：“意外事，总难免。”"},{"en":"You can’t judge a book by its cover, as the old saying goes.","cn":"老话说得好﹐人不可貌相。"}],"base":"say"},"sad":{"media":{"uk":"media/uk/sad__gb_1.mp3","us":"media/us/sad__us_1.mp3"},"oxford":{"phon":"sæd","pos":"adjective","senses":[{"en":"unhappy or showing unhappiness","cn":"悲哀的；难过的；显得悲哀的","sc":"unhappy","ex":{"en":"We are very sad to hear that you are leaving.","cn":"听说你要走了，我们十分难过。"}},{"en":"that makes you feel unhappy","cn":"令人悲哀的；让人难过的","sc":"unhappy","ex":{"en":"a sad story","cn":"悲伤的故事"}},{"en":"unacceptable; deserving blame or criticism","cn":"让人无法接受的；该受责备（或批评）的","sc":"unacceptable","ex":{"en":"a sad state of affairs","cn":"糟糕的局面"}},{"en":"boring or not fashionable","cn":"乏味的；过时的","lab":"informal","sc":"boring","ex":{"en":"Our teenage son thinks we're very sad.","cn":"我们十几岁的儿子认为我们非常难过。"}},{"en":"in poor condition","cn":"状况不佳","sc":"in poor condition","ex":{"en":"The salad consisted of a few leaves of sad-looking lettuce.","cn":"那道沙拉菜就是几片生菜的残叶。"}},{"en":"seasonal affective disorder (= a condition in which a person feels sad and tired during late autumn and winter when there is not much light from the sun)","cn":"季节性情感障碍","pos":"abbreviation"}]},"examples":[{"en":"He's a sad case — his wife died last year and he can't seem to manage without her.","cn":"他是个不幸的人，去年妻子去世了。没了妻子他好像就过不下去。"},{"en":"It's a sad fact that many of those killed were children.","cn":"让人难以接受的是遇难者中很多是孩子。"}],"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"","en":"SAD is an abbreviation for (缩略=) seasonal affective disorder."}]}},"satisfy":{"media":{"uk":"media/uk/satisfy__gb_1.mp3","us":"media/us/satisfy__us_1.mp3"},"oxford":{"phon":"ˈsætɪsfaɪ","pos":"verb","senses":[{"en":"to make somebody pleased by doing or giving them what they want","cn":"使满意；使满足","ex":{"en":"Nothing satisfies him—he's always complaining.","cn":"什么都难如他的意，他老在抱怨。"}},{"en":"to provide what is wanted, needed or asked for","cn":"满足（要求、需要等）","ex":{"en":"The food wasn't enough to satisfy his hunger.","cn":"这食物不足以让他解饿。"}},{"en":"to make somebody certain something is true or has been done","cn":"向…证实；使确信","lab":"formal","ex":{"en":"Her explanation did not satisfy the teacher.","cn":"她的解释没有让老师信服。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使满意;使满足;使高兴","en":"If someone or something satisfies you, they give you enough of what you want or need to make you pleased or contented.","ex":{"en":"The pace of change has not been quick enough to satisfy everyone","cn":"变化的速度还不够快，不能让所有人都满意。"}},{"pos":"VERB 动词","cn":"使确信;使弄清楚;使信服","en":"To satisfy someone that something is true or has been done properly means to convince them by giving them more information or by showing them what has been done.","ex":{"en":"He has to satisfy the environmental lobby that real progress will be made to cut emissions","cn":"他必须令环境游说团体相信在减排方面将取得实质性进展。"}},{"pos":"VERB 动词","cn":"符合，达到，满足(要求)","en":"If you satisfy the requirements for something, you are good enough or have the right qualities to fulfil these requirements.","ex":{"en":"The procedures should satisfy certain basic requirements.","cn":"这些程序应该符合某些基本要求。"}}]},"examples":[{"en":"Once I had satisfied myself (that) it was the right decision, we went ahead.","cn":"一旦我自己确信这个决定是正确的，我们便动手干了起来。"},{"en":"People need to be satisfied of the need for a new system.","cn":"需要使人们明白建立一个新体系的必要性。"}]},"safely":{"media":{"uk":"media/uk/safely__gb_1.mp3","us":"media/us/safely__us_1.mp3"},"oxford":{"phon":"ˈseɪfli","pos":"adverb","senses":[{"en":"without being harmed, damaged or lost","cn":"未受损伤（或损坏）；未丢失","ex":{"en":"The plane landed safely.","cn":"飞机安全着陆了。"}},{"en":"in a way that does not cause harm or that protects somebody/something from harm","cn":"安全地；无危害地","ex":{"en":"The bomb has been safely disposed of.","cn":"炸弹已安全处理。"}},{"en":"without much possibility of being wrong","cn":"不大可能出错地；有把握地","ex":{"en":"We can safely say that he will accept the job.","cn":"我们可以有把握地说，他会接受这份工作。"}},{"en":"without any possibility of the situation changing","cn":"安稳地；安定地","ex":{"en":"I thought the kids were safely tucked up in bed.","cn":"我以为孩子们好好地在床上睡觉呢。"}},{"en":"without any problems being caused; with no risk","cn":"没问题地；毫无风险地","ex":{"en":"These recommendations can safely be ignored.","cn":"这些推荐信大可不必理会。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"安全地;无危害地","en":"If something is done safely, it is done in a way that makes it unlikely that anyone will be harmed.","ex":{"en":"The waste is safely locked away until it is no longer radioactive","cn":"废料被安全储存起来，直到其不再有辐射性。"}},{"pos":"ADV 副词","cn":"安稳地;稳妥地;确定地","en":"You also use safely to say that there is no risk of a situation being changed.","ex":{"en":"Once events are safely in the past, this idea seems to become less alarming","cn":"一旦那些事件尘封为历史，这个想法似乎就变得不那么可怕了。"}}]},"examples":[{"en":"We can safely say that he will accept the job.","cn":"我们可以有把握地说，他会接受这份工作。"},{"en":"I thought the kids were safely tucked up in bed.","cn":"我以为孩子们好好地在床上睡觉呢。"}]},"satisfied":{"media":{"uk":"media/uk/satisfied__gb_1.mp3","us":"media/us/satisfied__us_1.mp3"},"oxford":{"phon":"ˈsætɪsfaɪd","pos":"adjective","senses":[{"en":"pleased because you have achieved something or because something that you wanted to happen has happened","cn":"满意的；满足的；欣慰的","ex":{"en":"a satisfied customer","cn":"满意的顾客"}},{"en":"believing or accepting that something is true","cn":"确信的；信服的","lab":"formal","ex":{"en":"I'm satisfied that they are telling the truth.","cn":"我确信他们讲的是真话。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"满意的;满足的;称心的","en":"If you are satisfied with something, you are happy because you have got what you wanted or needed.","ex":{"en":"We are not satisfied with these results.","cn":"我们对这些结果并不满意。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"确信的;信服的","en":"If you are satisfied that something is true or has been done properly, you are convinced about this after checking it.","ex":{"en":"People must be satisfied that the treatment is safe.","cn":"人们必须确信这种治疗方法是安全的。"}}]},"examples":[{"en":"She's never satisfied with what she's got.","cn":"她对自己的所得从不感到满足。"},{"en":"I'm satisfied that they are telling the truth.","cn":"我确信他们讲的是真话。"}],"base":"satisfy"},"savagery":{"media":{"uk":"media/uk/savagery__gb_1.mp3","us":"media/us/savagery__us_1.mp3"},"oxford":{"phon":"ˈsævɪdʒri","pos":"noun","senses":[{"en":"behaviour that is very cruel and violent","cn":"残暴行为","ex":{"en":"The police were shocked by the savagery of the attacks.","cn":"警方对这些惨无人道的袭击感到震惊。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"凶恶行为;残暴行径;兽性","en":"Savagery is extremely cruel and violent behaviour.","ex":{"en":"...the sheer savagery of war.","cn":"战争的残酷无情"}}]},"examples":[{"en":"The police were shocked by the savagery of the attacks.","cn":"警方对这些惨无人道的袭击感到震惊。"},{"en":"Local people were shocked by the savagery of the attack.","cn":"当地人为这次凶残的袭击感到震惊。"}]},"savvy":{"media":{"uk":"media/uk/savvy__gb_1.mp3","us":"media/us/savvy__us_1.mp3"},"oxford":{"phon":"ˈsævi","pos":"noun","senses":[{"en":"practical knowledge or understanding of something","cn":"实际知识；见识；了解","ex":{"en":"political savvy","cn":"政治见识"}},{"en":"having practical knowledge and understanding of something; having common sense","cn":"有见识的；懂实际知识的；通情达理的","ex":{"en":"savvy shoppers","cn":"精明的购物者"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"悟性;见识;实际知识","en":"If you describe someone as having savvy, you think that they have a good understanding and practical knowledge of something.","ex":{"en":"He is known for his political savvy and strong management skills.","cn":"他以睿智的政治头脑和强势的管理手腕出名。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有见识的;具有实际知识的;有经验的","en":"If you describe someone as savvy, you think that they show a lot of practical knowledge.","ex":{"en":"She was a pretty savvy woman.","cn":"她是个见过世面的漂亮女人。"}}]},"examples":[{"en":"savvy shoppers","cn":"精明的购物者"},{"en":"political savvy","cn":"政治见识"}]},"saliva":{"oxford":{"phon":"səˈlaɪvə","pos":"noun","senses":[{"en":"the liquid that is produced in your mouth that helps you to swallow food","cn":"唾液","ex":{"en":"The smell of food causes the saliva to flow.","cn":"食物的香味让人垂涎。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"唾液;口水;涎","en":"Saliva is the watery liquid that forms in your mouth and helps you to chew and digest food."}]},"media":{"uk":"media/uk/saliva__gb_1.mp3","us":"media/us/saliva__us_1.mp3"}},"salaried":{"media":{"uk":"media/uk/salaried__gb_1.mp3","us":"media/us/salaried__us_1.mp3"},"oxford":{"phon":"ˈsælərid","pos":"adjective","senses":[{"en":"receiving a salary","cn":"领薪水的","ex":{"en":"a salaried employee","cn":"领薪水的雇员"}},{"en":"for which a salary is paid","cn":"付给薪水的","ex":{"en":"a salaried position","cn":"付给薪水的职位"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(人)拿薪水的，有薪水的，受薪的","en":"Salaried people receive a salary from their job.","ex":{"en":"...salaried employees","cn":"拿薪水的雇员"}}]},"examples":[{"en":"a salaried position","cn":"付给薪水的职位"},{"en":"a salaried employee","cn":"领薪水的雇员"}]},"sandwiches":{"lemma":"sandwich"},"save":{"media":{"uk":"media/uk/save__gb_1.mp3","us":"media/us/save__us_1.mp3"},"oxford":{"phon":"seɪv","pos":"verb","senses":[{"en":"to keep somebody/something safe from death, harm, loss, etc.","cn":"救；救助；挽救；拯救","g":"[transitive]","lab":"figurative","sc":"keep safe","ex":{"en":"to save somebody’s life","cn":"救某人的命"}},{"en":"to keep money instead of spending it, especially in order to buy a particular thing","cn":"储蓄；攒钱","g":"[intransitive, transitive]","sc":"money","ex":{"en":"I'm not very good at saving.","cn":"我不大攒得住钱。"}},{"en":"to avoid wasting something or using more than necessary","cn":"节省；节约","g":"[transitive, intransitive]","sc":"not waste","ex":{"en":"People are looking for ways to save money.","cn":"人们正在寻找省钱的方法。"}},{"en":"to keep something to use or enjoy in the future or for somebody else to use","cn":"保留；保存","g":"[transitive]","sc":"keep for future/somebody else","ex":{"en":"He's saving his strength for the last part of the race.","cn":"他保存体力，以便在比赛的最后阶段发力。"}},{"en":"to make a computer keep data by putting a copy in a location where it will be stored","cn":"保存；存盘","g":"[transitive, intransitive]","sc":"computing","ex":{"en":"We recommend you save regularly by clicking on the update button.","cn":"我们建议您通过单击更新按钮定期保存。"}},{"en":"to collect something because you like it or for a special purpose","cn":"收集；收藏","g":"[transitive]","sc":"collect something","ex":{"en":"I've been saving theatre programmes for years.","cn":"我收藏剧院的节目单已有多年了。"}},{"en":"to avoid doing something difficult or unpleasant; to make somebody able to avoid doing something difficult or unpleasant","cn":"避免，免得（出现困难或不愉快的事）","g":"[transitive]","sc":"avoid something bad","ex":{"en":"The prize money saved her from having to find a job.","cn":"这笔奖金使她不用非得找工作。"}},{"en":"to prevent an opponent’s shot from going in the goal","cn":"救球（阻碍对方得分）","g":"[transitive, intransitive]","lab":"British English","sc":"in sport","ex":{"en":"to save a penalty","cn":"扑出一个点球"}},{"en":"to prevent a person's soul from going to hell","cn":"拯救；救赎","g":"[transitive, intransitive]","sc":"in christian belief","ex":{"en":"The missionaries believed they were sent to save souls.","cn":"传教士相信他们是被派去拯救灵魂的。"}},{"en":"an action by the goalkeeper that stops a goal being scored","cn":"（守门员的）救球","ex":{"en":"He made a spectacular save.","cn":"他那扑救的动作令人叹为观止。"},"pos":"noun"},{"en":"except something","cn":"除了；除…外","ex":{"en":"They knew nothing about her save her name.","cn":"除名字外，他们对她一无所知。"},"pos":"preposition"},{"en":"except","cn":"除了","ex":{"en":"They found out nothing more save that she had borne a child.","cn":"他们只查到她生过一个孩子，其他情况一无所知。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"拯救;搭救;挽救;救助","en":"If you save someone or something, you help them to avoid harm or to escape from a dangerous or unpleasant situation.","ex":{"en":"...a final attempt to save 40,000 jobs in Britain's troubled aero industry","cn":"为保住陷入困境中的英国航空业的 4 万份工作所作的最后一次努力"}},{"pos":"VERB 动词","cn":"储蓄;积攒;攒钱","en":"If you save, you gradually collect money by spending less than you get, usually in order to buy something that you want.","ex":{"en":"The majority of people intend to save, but find that by the end of the month there is nothing left","cn":"大多数人都打算存钱，但月末时就会发现已一文不剩。"}},{"pos":"VERB 动词","cn":"节省;节约","en":"If you save something such as time or money, you prevent the loss or waste of it.","ex":{"en":"It saves time in the kitchen to have things you use a lot within reach","cn":"把厨房里常用的东西放在触手可及的地方能节省做饭时间。"}},{"pos":"VERB 动词","cn":"保留;留下","en":"If you save something, you keep it because it will be needed later.","ex":{"en":"Drain the beans thoroughly and save the stock for soup","cn":"将豆角彻底控干，并把滤出的豆汁留下做汤。"}},{"pos":"VERB 动词","cn":"免去;省去;使免受","en":"If someone or something saves you from an unpleasant action or experience, they change the situation so that you do not have to do it or experience it.","ex":{"en":"The scanner will save risk and pain for patients","cn":"扫描仪将使病人免遭风险和痛苦。"}},{"pos":"VERB 动词","cn":"保存;存盘","en":"If you save data in a computer, you give the computer an instruction to store the data on a tape or disk.","ex":{"en":"Try to get into the habit of saving your work regularly","cn":"要努力养成经常将工作内容存盘的习惯。"}},{"pos":"VERB 动词","cn":"救(球)","en":"If a goalkeeper saves, or saves a shot, they succeed in preventing the ball from going into the goal.","ex":{"en":"He saved one shot when the ball hit him on the head.","cn":"球砸中他的脑袋，从而让他化解了一次射门。"}},{"pos":"PREP 介词","cn":"除…之外","en":"You can use save to introduce the only things, people, or ideas that your main statement does not apply to.","ex":{"en":"There is almost no water at all in Mochudi save that brought up from bore holes.","cn":"除了从钻孔中抽上来的水外，莫丘迪几乎滴水无存。"}},{"pos":"","cn":"","en":"to save someone's bacon→see: ; to save the day→see: ; to save face→see: ;"},{"pos":"","cn":"","en":"相关词组：save up"}]},"examples":[{"en":"She was fired, but she saved face by telling everyone she'd resigned.","cn":"明明是给解雇了，但她爱面子，逢人便说是她辞职了。"},{"en":"To save his own skin, he lied and blamed the accident on his friend.","cn":"为了自保，他竟然说谎，把事故的责任推到朋友身上。"}]},"saving":{"media":{"uk":"media/uk/saving__gb_1.mp3","us":"media/us/saving__us_1.mp3"},"oxford":{"phon":"ˈseɪvɪŋ","pos":"noun","senses":[{"en":"an amount of something such as time or money that you do not need to use or spend","cn":"节省物；节省；节约","g":"[countable]","ex":{"en":"Buy three and make a saving of 55p.","cn":"买三件就能节省 55 便士。"}},{"en":"money that you have saved, especially in a bank, etc.","cn":"储蓄金；存款","g":"[plural]","lab":"informal","ex":{"en":"He put all his savings into buying a boat.","cn":"他用全部积蓄买了一条船。"}},{"en":"that prevents the waste of the thing mentioned or stops it from being necessary","cn":"节约的；节省…的","ex":{"en":"labour-saving devices","cn":"节省人力的装置"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"节省;节约","en":"A saving is a reduction in the amount of time or money that is used or needed.","ex":{"en":"Fill in the form below and you will be making a saving of £6.60 on a one-year subscription.","cn":"填写以下表格，全年订阅即可为您节省 6.60英镑。"}},{"pos":"N-PLURAL 复数名词","cn":"(尤指在银行和购屋互助协会的)储蓄款，存款;积蓄","en":"Your savings are the money that you have saved, especially in a bank or a building society.","ex":{"en":"Her savings were in the Post Office Savings Bank.","cn":"她的钱存在邮政储蓄银行里。"}}]},"examples":[{"en":"With the new boiler you can make big savings on fuel bills.","cn":"用这种新锅炉，能省一大笔燃料开销。"},{"en":"I opened a savings account at my local bank.","cn":"我在本地银行开了一个储蓄账户。"}],"base":"save"},"sample":{"media":{"uk":"media/uk/sample__gb_1.mp3","us":"media/us/sample__us_1.mp3"},"oxford":{"phon":"ˈsɑːmpl","pos":"noun","senses":[{"en":"a number of people or things taken from a larger group and used in tests to provide information about the group","cn":"（抽查的）样本，样品","ex":{"en":"The interviews were given to a random sample of students.","cn":"随机抽选出部分学生进行了采访。"}},{"en":"a small amount of a substance taken from a larger amount and tested in order to obtain information about the substance","cn":"（化验的）取样，样本，样","ex":{"en":"a blood/urine/tissue/DNA sample","cn":"血样；尿样；组织／DNA 样本"}},{"en":"a small amount or example of something that can be looked at or tried to see what it is like","cn":"（作为标准或代表的）样品，货样","ex":{"en":"‘I'd like to see a sample of your work,’ said the manager.","cn":"“拿你作品的一个样本给我看看。”经理说。"}},{"en":"a piece of recorded music or sound that is used in a new piece of music","cn":"（用于新乐曲中的）节录乐曲，选录乐曲（或声音）","lab":"specialist","ex":{"en":"‘Candy’ includes a swirling sample from a Walker Brothers song.","cn":"《Candy》包含沃克兄弟歌曲中的旋转样本。"}},{"en":"to try a small amount of a particular food to see what it is like; to experience something for a short time to see what it is like","cn":"尝；品尝；尝试；体验","ex":{"en":"I sampled the delights of Greek cooking for the first time.","cn":"我第一次品尝到希腊美食。"},"pos":"verb"},{"en":"to test, question, etc., part of something or of a group of people in order to find out what the rest is like","cn":"抽样检验；取样；采样","lab":"specialist","ex":{"en":"12 per cent of the children sampled said they prefer cats to dogs.","cn":"在被抽样调查的孩子中，12% 的人说他们喜欢猫胜过喜欢狗。"},"pos":"verb"},{"en":"to record part of a piece of music, or a sound, in order to use it in a new piece of music","cn":"节录，选录（一段音乐或声音，用于新的乐曲中）","lab":"specialist","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"样品;货样","en":"A sample of a substance or product is a small quantity of it that shows you what it is like.","ex":{"en":"You'll receive samples of paint, curtains and upholstery","cn":"你将收到涂料、窗帘、家具垫衬套的样品。"}},{"pos":"N-COUNT 可数名词","cn":"(用于化验的)取样,样本","en":"A sample of a substance is a small amount of it that is examined and analysed scientifically.","ex":{"en":"They took samples of my blood.","cn":"他们取了我的血样。"}},{"pos":"N-COUNT 可数名词","cn":"(抽查的)样本;抽选人员;抽样","en":"A sample of people or things is a number of them chosen out of a larger group and then used in tests or used to provide information about the whole group.","ex":{"en":"We based our analysis on a random sample of more than 200 males.","cn":"我们随机抽查了 200 多名男性，并在此基础上进行分析。"}},{"pos":"VERB 动词","cn":"品尝;试尝","en":"If you sample food or drink, you taste a small amount of it in order to find out if you like it.","ex":{"en":"We sampled a selection of different bottled waters.","cn":"我们品尝了一系列不同品牌的瓶装水。"}},{"pos":"VERB 动词","cn":"体验;尝试","en":"If you sample a place or situation, you experience it for a short time in order to find out about it.","ex":{"en":"...the chance to sample a different way of life.","cn":"体验不同生活方式的机会"}},{"pos":"VERB 动词","cn":"节录,选录(乐曲)","en":"When musicians or pieces of their music are sampled, parts of their music are used by other musicians in their own work.","ex":{"en":"I don't actually mind being sampled as long as people give credit where it's due.","cn":"只要人们在适当处标明出处，我其实并不在乎自己的音乐被人节录。"}}]},"examples":[{"en":"12% of the children sampled said they prefer cats to dogs.","cn":"在被抽样调查的孩子中，12% 说他们喜欢猫胜过喜欢狗。"},{"en":"‘I'd like to see a sample of your work,’ said the manager. “","cn":"拿一件你做的货样给我看看。”经理说。"}]},"sag":{"oxford":{"phon":"sæɡ","pos":"noun","senses":[{"en":"the fact of hanging or bending down in the middle, especially because of weight or pressure","cn":"（尤指由于承重或受压）中间下垂，下凹","ex":{"en":"Weight has caused the sag.","cn":"承重导致下垂。"}},{"en":"a decrease in something","cn":"减少；减小；缩小","ex":{"en":"a sag in machinery orders","cn":"机械订单下降"}},{"en":"to hang or bend down in the middle, especially because of weight or pressure","cn":"（尤指由于承重或受压）中间下垂，下凹","g":"[intransitive]","ex":{"en":"a sagging roof","cn":"凹陷的房顶"},"pos":"verb"},{"en":"to become weaker or fewer","cn":"减弱；减少","g":"[intransitive]","ex":{"en":"Their share of the vote sagged badly at the last election.","cn":"在上次选举中他们的得票数大幅下跌。"},"pos":"verb"},{"en":"spinach (= a vegetable with large dark green leaves that are cooked or eaten in salads)","cn":"菠菜"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(中间部分)下垂，下弯，下陷","en":"When something sags, it hangs down loosely or sinks downwards in the middle.","ex":{"en":"The shirt's cuffs won't sag and lose their shape after washing","cn":"这件衬衫的袖口洗后照样挺括，不变形。"}},{"pos":"VERB 动词","cn":"(身体某部位)松弛，下垂","en":"When part of someone's body begins to sag, it starts to become less firm and hang down.","ex":{"en":"He is heavily built, but beginning to sag.","cn":"他体形健壮，但肌肉已经开始松弛。"}},{"pos":"VERB 动词","cn":"消衰;委顿;萎靡","en":"To sag means to become weaker.","ex":{"en":"The pound continued to sag despite four interventions by the Bank of England","cn":"尽管英格兰银行四次出手干预，英镑仍不改颓势。"}}]},"media":{"uk":"media/uk/sag__gb_2.mp3","us":"media/us/sag__us_1.mp3"},"examples":[{"en":"Their share of the vote sagged badly at the last election.","cn":"在上次选举中他们的得票比率大幅下跌。"},{"en":"The tent began to sag under the weight of the rain.","cn":"雨水使得帐篷中间开始下坠。"}]},"same":{"media":{"uk":"media/uk/same__gb_1.mp3","us":"media/us/same__us_1.mp3"},"oxford":{"phon":"seɪm","pos":"adjective","senses":[{"en":"exactly the one or ones referred to or mentioned; not different","cn":"同一的；相同的","ex":{"en":"We have lived in the same house for twenty years.","cn":"我们在同一座房子里住了二十年了。"}},{"en":"exactly like the one or ones referred to or mentioned","cn":"（与…）相同的，一模一样的","ex":{"en":"I bought the same car as yours (= another car of that type).","cn":"我买了一辆车，和你那辆一模一样。"}},{"en":"the same thing or things","cn":"（和…）同样的事物，相同的事物","lab":"informal","ex":{"en":"I would do the same again.","cn":"我愿再做同样的事。"},"pos":"pronoun"},{"en":"having the same number, colour, size, quality, etc.","cn":"（数目、颜色、大小、质量等）相同，一样","ex":{"en":"There are several brands and they're not all the same.","cn":"有好几个品牌，不一样的。"},"pos":"pronoun"},{"en":"the same person","cn":"同一个人","lab":"British English","ex":{"en":"‘Was that George on the phone?’ ‘The same (= yes, it was George).’","cn":"“是跟乔治通的电话吗？”“正是。”"},"pos":"pronoun"},{"en":"in the same way","cn":"同样","lab":"informal","ex":{"en":"We treat boys exactly the same as girls.","cn":"男孩、女孩我们完全同等对待。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"同样的;相同的","en":"If two or more things, actions, or qualities are the same, or if one is the same as another, they are very like each other in some way.","ex":{"en":"The houses were all the same — square, close to the street, needing paint","cn":"房子都一模一样——方方正正、临近街道、需要粉刷。"}},{"pos":"PHR-CONJ-SUBORD","cn":"与…相似;与…一样","en":"If something is happening the same as something else, the two things are happening in a way that is similar or exactly the same.","ex":{"en":"I mean, it's a relationship, the same as a marriage is a relationship","cn":"我的意思是它是一种人际关系，就如同婚姻也是一种人际关系一样。"}},{"pos":"ADJ 形容词","cn":"同一的;同样的","en":"You use same to indicate that you are referring to only one place, time, or thing, and not to different ones.","ex":{"en":"Bernard works at the same institution as Arlette","cn":"伯纳德和阿莱特在同一家机构工作。"}},{"pos":"ADJ 形容词","cn":"无变化的;一成不变的;千篇一律的","en":"Something that is still the same has not changed in any way.","ex":{"en":"Taking ingredients from the same source means the beers stay the same","cn":"取材自同一原材料意味着啤酒的口味始终如一。"}},{"pos":"PRON 代词","cn":"刚才提到的;上述的","en":"You use the same to refer to something that has previously been mentioned or suggested.","ex":{"en":"We made the decision which was right for us. Other parents must do the same","cn":"我们作出了对于我们而言正确的决定。其他父母也必须这么做。"}},{"pos":"PRON 代词","cn":"(用于商业信件、法案等文件中)上述事物，上述情况","en":"You use same to refer to something that has already been mentioned in a document such as a business letter or bill.","ex":{"en":"Wrist watches: £100. Inscription of same: £15.","cn":"腕表: 100英镑。在其上刻字: 15英镑。"}},{"pos":"CONVENTION 惯用语","cn":"我也是;我也一样","en":"You say 'same here' in order to suggest that you feel the same way about something as the person who has just spoken to you, or that you have done the same thing.","ex":{"en":"'Nice to meet you,' said Michael. 'Same here,' said Mary Ann","cn":"“很高兴见到你，”迈克尔说。“我也是，”玛丽·安说。"}},{"pos":"CONVENTION 惯用语","cn":"你也一样，你也是(用于致以同样的祝愿)","en":"You say 'same to you' in response to someone who wishes you well with something.","ex":{"en":"'Have a nice Easter.' — 'And the same to you Bridie.'","cn":"“复活节快乐。”——“你也一样，布赖迪。”"}},{"pos":"PHRASE 短语","cn":"同样的(饮品)再来一份","en":"You say 'same again' when you want to order another drink of the same kind as the one you have just had.","ex":{"en":"Give Roger another pint, Imogen, and I'll have the same again.","cn":"再给罗杰来一杯，伊莫金，我也再来一份同样的。"}},{"pos":"PHRASE 短语","cn":"仍然;依然;照样","en":"You can say all the same or just the same to introduce a statement which indicates that a situation or your opinion has not changed, in spite of what has happened or what has just been said.","ex":{"en":"I arranged to pay him the dollars when he got there, a purely private arrangement. All the same, it was illegal","cn":"我准备等他到那儿时付给他美元，纯属私人安排。不过同样也是非法的。"}},{"pos":"PHRASE 短语","cn":"对我完全一样;对我毫无区别;我都无所谓","en":"If you say 'It's all the same to me', you mean that you do not care which of several things happens or is chosen.","ex":{"en":"Whether I've got a moustache or not it's all the same to me","cn":"我留不留胡子都无所谓。"}},{"pos":"PHRASE 短语","cn":"同一事物;同一个人","en":"When two or more people or things are thought to be separate and you say that they are one and the same, you mean that they are in fact one single person or thing.","ex":{"en":"Luckily, Nancy's father and her attorney were one and the same person","cn":"幸运的是，南希的父亲就是她的律师。"}},{"pos":"PHRASE 短语","cn":"正是这个;同一个人(或事物)","en":"You say 'the same' or 'the very same' in reply to someone's question when you are saying that they have identified a person or thing correctly.","ex":{"en":"'This Sawtry guy, he is John Sawtry?' — 'Yes, sir. The very same.'","cn":"“这个叫索特里的小伙子，他是约翰·索特里吗？”——“是的，先生。正是他。”"}},{"pos":"","cn":"","en":"at the same time→see: ;"}]},"examples":[{"en":"His latest movie is just more of the same — exotic locations, car chases and a final shoot-out.","cn":"他的最新影片只不过是老一套，异国的场景、追车场面，以及最后的一场枪战。"},{"en":"It's all the same to me whether we eat now or later.","cn":"我们现在吃也行，过一会儿吃也行 — 我无所谓。"}]},"satirical":{"media":{"uk":"media/uk/satirical__gb_1.mp3","us":"media/us/satirical__us_1.mp3"},"oxford":{"phon":"səˈtɪrɪkl","pos":"adjective","senses":[{"en":"using satire to criticize somebody/something","cn":"讽刺的；讥讽的","ex":{"en":"a satirical magazine","cn":"讽刺杂志"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(画作、文章、喜剧)讽刺的，讥讽的","en":"A satirical drawing, piece of writing, or comedy show is one in which humour or exaggeration is used to criticize something.","ex":{"en":"...a satirical novel about London life in the late 80s.","cn":"讽刺 80 年代末伦敦生活的一部小说"}}]},"examples":[{"en":"a satirical magazine","cn":"讽刺杂志"},{"en":"the characteristic use of satire in Jonson’s work","cn":""}]},"safe":{"media":{"uk":"media/uk/safe__gb_1.mp3","us":"media/us/safe__us_1.mp3","img":["media/ldoce/img/safe.jpg"]},"oxford":{"phon":"seɪf","pos":"adjective","senses":[{"en":"protected from any danger, harm or loss","cn":"处境（或情况）安全；没有危险","g":"[not before noun]","sc":"protected","ex":{"en":"The children are quite safe here.","cn":"孩子们在这里十分安全。"}},{"en":"not likely to lead to any physical harm or danger","cn":"不损害（或危害）健康的；安全的","sc":"without physical danger","ex":{"en":"a safe and effective remedy for coughs and colds","cn":"治疗咳嗽和感冒的安全有效的方法"}},{"en":"not harmed, damaged, lost, etc.","cn":"未受伤害（或未遭损害、未丢失等）的","sc":"not harmed/lost","ex":{"en":"We were glad she let us know she was safe.","cn":"她告诉我们她平安无事，我们很高兴。"}},{"en":"where somebody/something is not likely to be in danger or to be lost","cn":"无危险的；物品不会丢失的","sc":"place","ex":{"en":"We all want to live in safer cities.","cn":"我们都希望住在比较安全的城市里。"}},{"en":"not involving much or any risk; not likely to be wrong or to upset somebody","cn":"风险小的；无风险的；不大会错的；不致冒犯别人的","lab":"disapproving","sc":"without risk","ex":{"en":"Electricity shares are still a safe investment.","cn":"电力股仍然是小风险投资。"}},{"en":"doing an activity in a careful way","cn":"谨慎的；小心的","g":"[usually before noun]","sc":"person","ex":{"en":"a safe driver","cn":"谨慎的司机"}},{"en":"based on good evidence","cn":"有确凿证据的","sc":"law","ex":{"en":"a safe verdict","cn":"确当的裁定"}},{"en":"used by young people to show that they approve of somebody/something","cn":"（年轻人用语，表示赞同）很好的，不错的，令人满意的","lab":"British English, informal，，","sc":"approving","ex":{"en":"I like him, he's safe.","cn":"我喜欢他，他很不错。"}},{"en":"used by young people as a way of accepting something that is offered","cn":"（年轻人用语，表示接受）可以","lab":"British English, informal，，","sc":"approving","ex":{"en":"‘You want some?’ ‘Yeah, safe.’","cn":"“你要一些吗？”“好的。”"}},{"en":"a strong metal box or cupboard with a complicated lock, used for storing valuable things in, for example, money or jewellery","cn":"保险箱；保险柜","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(对身体)无害的，安全的","en":"Something that is safe does not cause physical harm or danger.","ex":{"en":"Officials arrived to assess whether it is safe to bring emergency food supplies into the city","cn":"官员们赶来评估向该市调拨紧急救援食品是否安全。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不会受伤的;不会受损的","en":"If a person or thing is safe from something, they cannot be harmed or damaged by it.","ex":{"en":"In the future people can go to a football match knowing that they are safe from hooliganism","cn":"今后人们去看足球比赛时可以不必担心会受到足球流氓的骚扰。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"安全的;没有受伤的;安然无恙的","en":"If you are safe, you have not been harmed, or you are not in danger of being harmed.","ex":{"en":"Where is Sophy? Is she safe?","cn":"索菲在哪里？她没有受伤吧？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方)安全的，可靠的，保险的","en":"A safe place is one where it is unlikely that any harm, damage, or unpleasant things will happen to the people or things that are there.","ex":{"en":"Many refugees have fled to safer areas","cn":"许多难民已经逃往了更安全的地方。"}},{"pos":"ADJ 形容词","cn":"(旅途)平安的，无损的，一路顺风的","en":"If people or things have a safe journey, they reach their destination without harm, damage, or unpleasant things happening to them.","ex":{"en":"'I'm heading back to Ireland again for another weekend.' — 'Have a safe journey.'","cn":"“我要再回爱尔兰过一个周末。”——“一路平安。”"}},{"pos":"ADJ 形容词","cn":"(距离)安全的，不会遭到伤害的","en":"If you are at a safe distance from something or someone, you are far enough away from them to avoid any danger, harm, or unpleasant effects.","ex":{"en":"I shall conceal myself at a safe distance from the battlefield","cn":"我会躲在一个远离战场的安全地带。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不会丢失的;志在必得的;稳操胜券的","en":"If something you have or expect to obtain is safe, you cannot lose it or be prevented from having it.","ex":{"en":"We as consumers need to feel confident that our jobs are safe before we will spend spare cash","cn":"我们作为消费者在把闲钱花掉之前，需要确信自己不会失业。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行动)风险小的，万无一失的，保险的","en":"A safe course of action is one in which there is very little risk of loss or failure.","ex":{"en":"Electricity shares are still a safe investment","cn":"电力股仍然是低风险投资。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"四平八稳的;缺乏新意的;不够刺激的","en":"If you disapprove of something because you think it is not very exciting or original, you can describe it as safe .","ex":{"en":"...frustrated artists who became lawyers at an early age because it seemed a safe option","cn":"趁年轻改行从事律师这一看似稳定的职业的失意落泊的艺术家们"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有把握的;不会有错的;可以肯定的","en":"If it is safe to say or assume something, you can say it with very little risk of being wrong.","ex":{"en":"I think it is safe to say that very few students expend the effort to do quality work in school","cn":"我认为可以肯定地说学校里很少有学生肯为学好功课下功夫。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(秘密)不会被泄漏的，会被保守的，安全的","en":"If you say to someone that their secret is safe with you, you are promising not to tell it to anyone.","ex":{"en":"Don't worry, Mr Palin, your secret is safe with me.","cn":"别担心，佩林先生，我会保守你的秘密。"}},{"pos":"N-COUNT 可数名词","cn":"保险柜","en":"A safe is a strong metal cupboard with special locks, in which you keep money, jewellery, or other valuable things.","ex":{"en":"The files are now in a safe to which only he has the key.","cn":"文件目前放在一个只有他才能打开的保险柜里。"}},{"pos":"PHRASE 短语","cn":"得到妥善照顾的;由可靠的人保护(或保管)的","en":"If you say that a person or thing is in safe hands, or is safe in someone's hands, you mean that they are being looked after by a reliable person and will not be harmed.","ex":{"en":"I had a huge responsibility to ensure these packets remained in safe hands","cn":"我负有确保这些包裹得到妥善保管的重大责任。"}},{"pos":"PHRASE 短语","cn":"非常安全的;绝对安全的","en":"If you say that something or someone is as safe as houses, you mean that they are completely safe.","ex":{"en":"The Government insisted that Britain's nuclear power stations are as safe as houses.","cn":"英国政府坚称英国的核电站非常安全。"}},{"pos":"PHRASE 短语","cn":"使(某地)适合开展(某活动);使适宜","en":"If someone tries to make a place safe for a particular activity, they try to make the place suitable for that activity, although their efforts may have very undesirable effects.","ex":{"en":"Why did these men fight and die? Supposedly it was to make the world safe for democracy.","cn":"为什么这些人战死了呢？据说，是为了在全世界实现民主。"}},{"pos":"PHRASE 短语","cn":"谨慎行事;避免冒险","en":"If you play safe or play it safe, you do not take any risks.","ex":{"en":"If you want to play safe, cut down on the amount of salt you eat","cn":"如果想要谨慎点的话，就减少盐的摄入量。"}},{"pos":"PHRASE 短语","cn":"谨慎为是;以防万一;为安全起见","en":"If you say you are doing something to be on the safe side, you mean that you are doing it in case something undesirable happens, even though this may be unnecessary.","ex":{"en":"You might still want to go for an X-ray, however, just to be on the safe side.","cn":"不过，为稳妥起见，你可能还想要照一个 X 光。"}},{"pos":"PHRASE 短语","cn":"宁可事先谨慎有余，不要事后追悔莫及","en":"If you say 'it's better to be safe than sorry', you are advising someone to take action in order to avoid possible unpleasant consequences later, even if this seems unnecessary.","ex":{"en":"Don't be afraid to have this checked by a doctor — better safe than sorry!","cn":"不要害怕找医生检查一下——宁求稳妥以免后悔！"}},{"pos":"PHRASE 短语","cn":"平平安安的;安然无恙的","en":"You say that someone is safe and sound when they are still alive or unharmed after being in danger.","ex":{"en":"All I'm hoping for is that wherever Trevor is he will come home safe and sound.","cn":"我只希望不管特雷弗在哪里，他都能平平安安回家。"}},{"pos":"","cn":"","en":"a safe pair of hands→see: ; safe in the knowledge→see: ;"}]},"examples":[{"en":"It's safe to assume (that) there will always be a demand for new software.","cn":"可以肯定地认为，人们对新的软件一直有需求。"},{"en":"I've left the kids in safe hands — with my parents.","cn":"我把孩子托付给了靠得住的人，就是我父母。"}]},"sap":{"oxford":{"phon":"sæp","pos":"noun","senses":[{"en":"the liquid in a plant or tree that carries food to all its parts","cn":"（植物体内运送养分的）液，汁","g":"[uncountable]","ex":{"en":"Maple syrup is made from sap extracted from the sugar maple tree.","cn":"槭糖浆是用糖槭树中提取的树液制成的。"}},{"en":"a stupid person that you can easily trick, or treat unfairly","cn":"笨蛋；易上当的人","g":"[countable]","lab":"especially North American English, informal，，","ex":{"en":"The poor sap never knew what was going on behind his back.","cn":"这个可怜的傻瓜永远不知道他背后发生了什么。"}},{"en":"to make something/somebody weaker; to destroy something gradually","cn":"使虚弱；削弱；逐渐破坏","ex":{"en":"The hot sun sapped our energy.","cn":"火辣辣的太阳烤得我们虚软无力。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"消耗(精力);削弱(信心)","en":"If something saps your strength or confidence, it gradually weakens or destroys it.","ex":{"en":"I was afraid the sickness had sapped my strength","cn":"我担心患病已让我元气大伤。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(植物的)液，汁","en":"Sap is the watery liquid in plants and trees.","ex":{"en":"The leaves, bark and sap are also common ingredients of local herbal remedies.","cn":"树叶、树皮和树汁也是当地草药的常用药材。"}},{"pos":"N-COUNT 可数名词","cn":"笨蛋;傻瓜","en":"If you describe someone as a sap, you think they are foolish.","ex":{"en":"...her poor sap of a husband.","cn":"她可怜的傻瓜丈夫"}}]},"media":{"uk":"media/uk/sap__gb_1.mp3","us":"media/us/sap__us_1.mp3"},"examples":[{"en":"Maple syrup is made from sap extracted from the sugar maple tree.","cn":"槭糖浆是用糖槭树中提取的树液制成的。"},{"en":"The hot sun sapped our energy.","cn":"火辣辣的太阳烤得我们虚软无力。"}]},"sake":{"media":{"uk":"media/uk/sake__gb_1.mp3","us":"media/us/sake__us_1.mp3"},"oxford":{"phon":"ˈsɑːki","pos":"noun","senses":[{"en":"a Japanese alcoholic drink made from rice","cn":"日本清酒"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"由于;为了;因为…的缘故","en":"If you do something for the sake of something, you do it for that purpose or in order to achieve that result. You can also say that you do it for something's sake .","ex":{"en":"Let's assume for the sake of argument that we manage to build a satisfactory database","cn":"为了便于讨论，不妨假定我们成功地建立了一个令人满意的数据库。"}},{"pos":"PHRASE 短语","cn":"为…本身的缘故;鉴于…本身的价值","en":"If you do something for its own sake, you do it because you want to, or because you enjoy it, and not for any other reason. You can also talk about, for example, art for art's sake or sport for sport's sake .","ex":{"en":"Economic change for its own sake did not appeal to him","cn":"经济变化本身对他并没有吸引力。"}},{"pos":"PHRASE 短语","cn":"看在…份上;为了帮助(某人)","en":"When you do something for someone's sake, you do it in order to help them or make them happy.","ex":{"en":"I trust you to do a good job for Stan's sake","cn":"我拜托你看在斯坦的份上好好干。"}},{"pos":"PHRASE 短语","cn":"(用于加强请求、疑问的语气或表示厌烦、恼怒)看在上帝份上，天哪，行行好，拜托","en":"Some people use expressions such as for God's sake ,for heaven's sake ,for goodness sake, or for Pete's sake in order to express annoyance or impatience, or to add force to a question or request. The expressions 'for God's sake' and 'for Christ's sake' could cause offence.","ex":{"en":"For goodness sake, why didn't you ring me?","cn":"天哪，为什么你不给我打电话？"}}]},"examples":[{"en":"Let's suppose, for the sake of argument (= in order to have a discussion), that interest rates went up by 2%.","cn":"为了便于讨论，不妨设想利率提高了 2%。"},{"en":"You can do it. Please, for my sake.","cn":"这个你是能做的。求你了，就算为了我。"}]},"saint":{"oxford":{"phon":"seɪnt","pos":"noun","senses":[{"en":"a person that the Christian Church recognizes as being very holy, because of the way they have lived or died","cn":"（因其言行而被基督教会追封的）圣人，圣徒","ex":{"en":"St John","cn":"圣约翰"}},{"en":"a very good, kind or patient person","cn":"圣人般的人（指特别善良、仁爱或有耐性的人）","ex":{"en":"She's a saint to go on living with that man.","cn":"能继续和那个男人一起生活，她简直是圣人。"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"(基督教正式追封的)圣徒，圣人","en":"A saint is someone who has died and been officially recognized and honoured by the Christian church because his or her life was a perfect example of the way Christians should live.","ex":{"en":"Every parish was named after a saint.","cn":"每个教区都以某位圣徒的名字命名。"}},{"pos":"N-COUNT 可数名词","cn":"至善的人;极有耐心的人;道德高尚的人;圣人般的人","en":"If you refer to a living person as a saint, you mean that they are extremely kind, patient, and unselfish.","ex":{"en":"My girlfriend is a saint to put up with me.","cn":"能够忍受我，我的女朋友真的很有耐心。"}}]},"media":{"uk":"media/uk/saint__gb_1.mp3","us":"media/us/saint__us_1.mp3"},"examples":[{"en":"She's a saint to go on living with that man.","cn":"能继续和那个男人一起生活，她简直是圣人。"},{"en":"His behaviour would try the patience of a saint.","cn":"他的行为就是再有修养的人也难以忍受。"}]},"sadly":{"media":{"uk":"media/uk/sadly__gb_1.mp3","us":"media/us/sadly__us_1.mp3"},"oxford":{"phon":"ˈsædli","pos":"adverb","senses":[{"en":"in a sad way","cn":"悲伤地；伤心地","ex":{"en":"‘I'm so sorry,’ she said sadly.","cn":"“我很难过，”她伤感地说。"}},{"en":"unfortunately","cn":"不幸地","ex":{"en":"Sadly, after eight years of marriage they had grown apart.","cn":"不幸的是，结婚八年后，他们的感情日渐淡薄了。"}},{"en":"very much and in a way that makes you sad","cn":"极为；苦苦地","ex":{"en":"She will be sadly missed.","cn":"人们会很想她的。"}}]},"examples":[{"en":"Sadly, after eight years of marriage they had grown apart.","cn":"不幸的是，结婚八年后，他们的感情日渐淡漠了。"},{"en":"If you think I'm going to help you again, you're sadly (= completely) mistaken.","cn":"你要是以为我还会再帮助你，那你就大错特错了。"}]},"salary":{"media":{"uk":"media/uk/salary__gb_1.mp3","us":"media/us/salary__us_1.mp3"},"oxford":{"phon":"ˈsæləri","pos":"noun","senses":[{"en":"money that employees receive for doing their job, especially professional employees or people working in an office, usually paid every month","cn":"薪金，薪水（尤指按月发放的）","lab":"British English","ex":{"en":"an annual salary of $40 000","cn":"4 万美元的年薪"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(尤指从事某一职业的人获得的)薪水，薪金,工资","en":"A salary is the money that someone is paid each month by their employer, especially when they are in a profession such as teaching, law, or medicine.","ex":{"en":"...the lawyer was paid a huge salary","cn":"那个律师薪水很高。"}}]},"examples":[{"en":"She's on a salary of £24 000.","cn":"她的薪金是 24 000 英镑。"},{"en":"( BrE ) He gets a basic salary plus commission.","cn":"他领取基本薪金，外加佣金。"}]},"satellite":{"media":{"uk":"media/uk/satellite__gb_1.mp3","us":"media/us/satellite__us_1.mp3","img":["media/ldoce/img/satellite.jpg"]},"oxford":{"phon":"ˈsætəlaɪt","pos":"noun","senses":[{"en":"an electronic device that is sent into space and moves around the earth or another planet. It is used for communicating by radio, television, etc. and for gathering information.","cn":"人造卫星","lab":"British English","ex":{"en":"a weather/communications/spy satellite","cn":"气象／通信／间谍卫星"}},{"en":"a natural object that moves around a larger natural object in space","cn":"卫星","ex":{"en":"The moon is a satellite of earth.","cn":"月球是地球的卫星。"}},{"en":"a town, a country or an organization that is controlled by and depends on another larger or more powerful one","cn":"卫星城；卫星国；外围组织","ex":{"en":"Following the Second World War it became a satellite state of the Soviet Union.","cn":"第二次世界大战之后，它成了苏联的一个卫星国。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"人造卫星","en":"A satellite is an object which has been sent into space in order to collect information or to be part of a communications system. Satellites move continually round the earth or around another planet.","ex":{"en":"The rocket launched two communications satellites","cn":"火箭发射了两颗通信卫星。"}},{"pos":"ADJ 形容词","cn":"(电视)使用卫星技术的;卫视的","en":"Satellite television is broadcast using a satellite.","ex":{"en":"They have four satellite channels.","cn":"他们有 4 个卫星频道。"}},{"pos":"N-COUNT 可数名词","cn":"卫星","en":"A satellite is a natural object in space that moves round a planet or star.","ex":{"en":"...the satellites of Jupiter.","cn":"木星的卫星"}},{"pos":"N-COUNT 可数名词","cn":"卫星国;附属国;卫星区;卫星组织","en":"You can refer to a country, area, or organization as a satellite when it is controlled by or depends on a larger and more powerful one.","ex":{"en":"Italy became a satellite state of Germany by the end of the 1930s.","cn":"意大利在 20 世纪 30 年代末成了德国的附庸。"}}]},"examples":[{"en":"The interview came live by satellite from Hollywood.","cn":"采访画面是通过卫星从好莱坞现场传来的。"},{"en":"The moon is a satellite of earth.","cn":"月球是地球的卫星。"}]},"salesperson":{"oxford":{"phon":"ˈseɪlzpɜːsn","pos":"noun","senses":[{"en":"a person whose job is to sell goods, for example, in a shop","cn":"售货员；推销员"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"店员;售货员;推销员","en":"A salesperson is a person who sells things, either in a shop or directly to customers on behalf of a company."}]},"media":{"uk":"media/uk/salesperson__gb_1.mp3","us":"media/us/salesperson__us_1.mp3"}},"sank":{"lemma":"sink","media":{"uk":"media/uk/sank__gb_1.mp3","us":"media/us/sank__us_1.mp3"}},"salty":{"oxford":{"phon":"ˈsɔːlti","pos":"adjective","senses":[{"en":"containing or tasting of salt","cn":"含盐的；咸的","ex":{"en":"salty food","cn":"咸的食物"}},{"en":"funny and sometimes slightly rude","cn":"有趣的；逗笑的；有趣而略嫌粗俗的","lab":"old-fashioned","ex":{"en":"She has a salty sense of humour.","cn":"她有一种咸涩的幽默感。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"含盐的;咸的","en":"Something that is salty contains salt or tastes of salt.","ex":{"en":"...salty foods such as ham and bacon.","cn":"火腿和熏肉等咸味食品"}}]},"media":{"uk":"media/uk/salty__gb_1.mp3","us":"media/us/salty__us_1.mp3"},"examples":[{"en":"She could taste the saltiness of her tears.","cn":"她尝到了她眼泪的咸味。"},{"en":"salty sea air","cn":"海边带咸味的空气"}]},"sails":{"lemma":"sail"},"sardonic":{"media":{"uk":"media/uk/sardonic__gb_1.mp3","us":"media/us/sardonic__us_1.mp3"},"oxford":{"phon":"sɑːˈdɒnɪk","pos":"adjective","senses":[{"en":"showing that you think that you are better than other people and do not take them seriously","cn":"轻慢的；轻蔑的；嘲弄的","ex":{"en":"a sardonic smile","cn":"讪笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷嘲的;讥讽的","en":"If you describe someone as sardonic, you mean their attitude to people or things is humorous but rather critical.","ex":{"en":"...a big, sardonic man, who intimidated his students.","cn":"令学生胆怯的身材魁梧、爱嘲讽人的男人"}}]},"examples":[{"en":"a sardonic smile","cn":"讪笑"},{"en":"He looked at her with sardonic amusement.","cn":"他带着嘲讽的愉悦神情看着她。"}]},"sandwiched":{"lemma":"sandwich"},"satisfying":{"media":{"uk":"media/uk/satisfying__gb_1.mp3","us":"media/us/satisfying__us_1.mp3"},"oxford":{"phon":"ˈsætɪsfaɪɪŋ","pos":"adjective","senses":[{"en":"giving pleasure because it provides something you need or want","cn":"令人满意（或满足）的","ex":{"en":"a satisfying meal","cn":"可口的饭菜"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人高兴的;(尤指)令人有满足感的","en":"Something that is satisfying makes you feel happy, especially because you feel you have achieved something.","ex":{"en":"I found wood carving satisfying.","cn":"我觉得木雕能给人带来满足感。"}}]},"examples":[{"en":"It's satisfying to play a game really well.","cn":"一种游戏玩得特别好是一桩惬意的事。"},{"en":"Nursing can be a very rewarding career.","cn":"做护士可以是非常有意义的职业。"}],"base":"satisfy"},"sauce":{"oxford":{"phon":"sɔːs","pos":"noun","senses":[{"en":"a thick liquid that is eaten with food to add taste to it","cn":"调味汁；酱","g":"[countable, uncountable]","ex":{"en":"tomato/cranberry/chilli sauce","cn":"番茄／蔓越橘／辣椒调味汁"}},{"en":"talk or behaviour that is annoying or shows no respect","cn":"讨厌的话（或举动）；无礼的话（或举动）","g":"[uncountable]","lab":"British English, old-fashioned, informal，，，，"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"沙司;调味汁;酱;佐料","en":"A sauce is a thick liquid which is served with other food.","ex":{"en":"...pasta cooked in a sauce of garlic, tomatoes, and cheese.","cn":"用蒜、西红柿和奶酪作酱汁做成的意大利面"}}]},"media":{"uk":"media/uk/sauce__gb_1.mp3","us":"media/us/sauce__us_1.mp3"},"examples":[{"en":"ice cream with a hot fudge sauce","cn":"浇了热巧克力酱的冰淇淋"},{"en":"tomato/cranberry/chilli, etc. sauce","cn":"番茄、越橘、辣椒等调味汁"}]},"sail":{"oxford":{"phon":"seɪl","pos":"verb","senses":[{"en":"to travel on water using sails or an engine","cn":"（船）航行；（人）乘船航行","g":"[intransitive, transitive]","ex":{"en":"to sail into harbour","cn":"驶入海港"}},{"en":"to control or travel on a boat with a sail, especially as a sport","cn":"驾驶（或乘坐）帆船航行（尤指作为体育运动）","g":"[intransitive, transitive]","ex":{"en":"We spent the weekend sailing off the south coast.","cn":"我们在南部海岸一带驾帆船度过了周末。"}},{"en":"to begin a journey on water","cn":"起航","g":"[intransitive]","ex":{"en":"We sail at 2 p.m. tomorrow.","cn":"我们明天下午两点起航。"}},{"en":"to move quickly and smoothly in a particular direction; (of people) to move in a confident manner","cn":"掠；飘；浮游；（人）昂首而行，气宇轩昂地走","g":"[intransitive]","ex":{"en":"clouds sailing across the sky","cn":"飘过天空的云彩"}},{"en":"a sheet of strong cloth which the wind blows against to make a boat or ship travel through the water","cn":"帆","g":"[countable, uncountable]","ex":{"en":"As the boat moved down the river the wind began to fill the sails.","cn":"船顺河而下，风逐渐胀满了帆。"},"pos":"noun"},{"en":"a trip in a boat or ship","cn":"乘船航行","g":"[singular]","ex":{"en":"We went for a sail.","cn":"我们乘船兜了一趟风。"},"pos":"noun"},{"en":"a set of boards attached to the arm of a windmill","cn":"（风车的）翼板","g":"[countable]","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"帆","en":"Sails are large pieces of material attached to the mast of a ship. The wind blows against the sails and pushes the ship along.","ex":{"en":"The white sails billow with the breezes they catch.","cn":"一张张白帆随着微风舞动。"}},{"pos":"VERB 动词","cn":"(船)航行，行驶","en":"You say a ship sails when it moves over the sea.","ex":{"en":"The trawler had sailed from the port of Zeebrugge","cn":"拖网渔船已经驶离了泽布吕赫港。"}},{"pos":"V-ERG 及物/不及物动词","cn":"驾驶(帆船);(船)扬帆行驶","en":"If you sail a boat or if a boat sails, it moves across water using its sails.","ex":{"en":"I shall get myself a little boat and sail her around the world","cn":"我要给自己买一条小船，驾着它环游世界。"}},{"pos":"N-COUNT 可数名词","cn":"(风车的)翼板","en":"The sails on a windmill are the long flat parts that are turned by the wind.","ex":{"en":"...a windmill, its sails turning in the breeze.","cn":"翼板在微风中转动的风车"}},{"pos":"VERB 动词","cn":"(人、物体)轻快而迅速地移动，飘过，飞过，掠过","en":"If a person or thing sails somewhere, they move there smoothly and fairly quickly.","ex":{"en":"We got into the lift and sailed to the top floor","cn":"我们进了电梯，很快到了顶层。"}},{"pos":"PHRASE 短语","cn":"启航;开船","en":"When a ship sets sail, it leaves a port.","ex":{"en":"He loaded his vessel with another cargo and set sail","cn":"他给自己的船装上另一批货后便启航了。"}},{"pos":"PHRASE 短语","cn":"坐帆船;乘帆船","en":"If you cross the sea under sail, you cross it in a ship that has sails rather than an engine.","ex":{"en":"...the challenge and fun of going to sea under sail.","cn":"扬帆出海的挑战和乐趣"}},{"pos":"","cn":"","en":"to sail close to the wind→see: ; to take the wind out of someone's sails→see: ;"},{"pos":"","cn":"","en":"相关词组：sail through"}]},"media":{"uk":"media/uk/sail__gb_1.mp3","us":"media/us/sail__us_1.mp3"},"examples":[{"en":"We spent the weekend sailing off the south coast.","cn":"我们在南部海岸一带驾帆船度过了周末。"},{"en":"He sailed for the West Indies from Portsmouth.","cn":"他从朴次茅斯起航，向西印度群岛进发。"}]},"sarcasm":{"oxford":{"phon":"ˈsɑːkæzəm","pos":"noun","senses":[{"en":"a way of using words that are the opposite of what you mean in order to be unpleasant to somebody or to make fun of them","cn":"讽刺；嘲讽；挖苦","ex":{"en":"‘That will be useful,’ she snapped with heavy sarcasm (= she really thought it would not be useful at all).","cn":"“还真有用咧。”她狠狠挖苦道。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"讽刺;嘲笑;挖苦","en":"Sarcasm is speech or writing which actually means the opposite of what it seems to say. Sarcasm is usually intended to mock or insult someone.","ex":{"en":"'What a pity,' Graham said with a hint of sarcasm","cn":"“太遗憾了，”格雷厄姆略带挖苦地说道。"}}]},"media":{"uk":"media/uk/sarcasm__gb_1.mp3","us":"media/us/sarcasm__us_1.mp3"},"examples":[{"en":"‘That will be useful,’ she snapped with heavy sarcasm (= she really thought it would not be useful at all). “","cn":"还真有用咧。”她狠狠挖苦道。"},{"en":"a hint/touch/trace of sarcasm in his voice","cn":"他话语中的几分嘲讽"}]},"sacking":{"oxford":{"phon":"ˈsækɪŋ","pos":"noun","senses":[{"en":"an act of sacking somebody (= dismissing them from their job)","cn":"解雇","g":"[countable]","ex":{"en":"A council chief faced calls for his sacking yesterday over allegations that he had accepted bribes.","cn":"一名市政部门的主管昨日因受贿指控而被要求撤职。"}},{"en":"a type of rough cloth made from jute, etc., used for making sacks","cn":"粗麻布；麻袋布","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"麻袋布;粗麻布","en":"Sacking is rough woven material that is used to make sacks."},{"pos":"N-COUNT 可数名词","cn":"解雇;开除;炒鱿鱼","en":"A sacking is when an employer tells a worker to leave their job.","ex":{"en":"...the sacking of twenty-three thousand miners.","cn":"23,000 名矿工被解雇"}}]},"media":{"uk":"media/uk/sacking__gb_1.mp3","us":"media/us/sacking__us_1.mp3"},"base":"sack"},"sated":{"media":{"uk":"media/uk/sated__gb_1.mp3","us":"media/us/sated__us_1.mp3"},"oxford":{"phon":"ˈseɪtɪd","pos":"adjective","senses":[{"en":"having had so much of something that you do not need any more","cn":"餍足；餍腻","ex":{"en":"sated with pleasure","cn":"倦于享乐"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过度满足的;过多享用的;餍腻的","en":"If you are sated with something, you have had more of it than you can enjoy at one time.","ex":{"en":"...children happily sated with ice cream.","cn":"尽情享用冰激凌的孩子们"}}]},"examples":[{"en":"sated with pleasure","cn":"倦于享乐"}]},"salmon":{"media":{"uk":"media/uk/salmon__gb_1.mp3","us":"media/us/salmon__us_1.mp3","img":["media/ldoce/img/salmon.jpg"]},"oxford":{"phon":"ˈsæmən","pos":"noun","senses":[{"en":"a large fish that has silver skin and is pink inside and is used for food. Salmon live in the sea but swim up rivers to lay their eggs.","cn":"鲑；大麻哈鱼","ex":{"en":"a whole salmon","cn":"一整条鲑鱼"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鲑鱼;大麻哈鱼","en":"A salmon is a large silver-coloured fish.","ex":{"en":"... a splendid lunch of smoked salmon.","cn":"有熏鲑鱼的丰盛午餐"}}]},"examples":[{"en":"wild and farmed salmon","cn":"野生和人工养殖的鲑鱼"},{"en":"a whole salmon","cn":"一整条鲑鱼"}]},"sat":{"media":{"uk":"media/uk/sat__gb_1.mp3","us":"media/us/sat__us_1.mp3"},"oxford":{"phon":"","pos":"noun","senses":[{"en":"(in the US) a test taken by high school students who want to go to a college or university (the abbreviation for ‘Scholastic Assessment Test’)","cn":"学术能力评估测试（高中生升大学须通过的考试，全写为 Scholastic Assessment Test）","ex":{"en":"to take the SAT","cn":"参加学术能力评估测试"}},{"en":"(in England) a test taken by children at the ages of 7 and 11, now officially called NCT (the abbreviation for ‘Standard Assessment Task’)","cn":"标准课业测评考试（儿童在 7 岁和 11 岁时参加，全写为 Standard Assessment Task，现称为 NCT）"},{"en":"Saturday","cn":"星期六","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"学业能力倾向测验(升读大学需要参加的一种考试)","en":"The SAT is an examination which is often taken by students who wish to enter a college or university. SAT is an abbreviation for (缩略=) 'Scholastic Aptitude Test'."},{"pos":"N-COUNT 可数名词","cn":"(针对七岁学童的)标准课业测评考试","en":"SATs are a set of tasks given to seven-year-old schoolchildren in order to test their ability. SAT is an abbreviation for (缩略=) 'Standard Assessment Task'."}]},"examples":[{"en":"I scored 1050 on the SAT.","cn":"我在学业能力倾向测验中得了 1 050 分。"},{"en":"to take the SAT","cn":"参加学业能力倾向测验"}]},"sailors":{"lemma":"sailor"},"sally":{"media":{"uk":"media/uk/sally__gb_1.mp3","us":"media/us/sally__us_1.mp3"},"oxford":{"phon":"ˈsæli","pos":"noun","senses":[{"en":"a remark that is intended to entertain somebody or make them laugh","cn":"俏皮话","ex":{"en":"Everyone waited for his next sally.","cn":"大家都在等待着他的下一次出击。"}},{"en":"a sudden attack by an enemy","cn":"出击；突袭"},{"en":"a first name for girls, sometimes short for Sarah","cn":"萨莉（女子名，有时为 Sarah 缩写）","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"俏皮话;妙语;隽语","en":"Sallies are clever and amusing remarks.","ex":{"en":"He had thus far succeeded in fending off my conversational sallies.","cn":"他迄今为止一直不为我说的俏皮话所动。"}},{"pos":"VERB 动词","cn":"突然冲出;奋身前往;大胆迈入","en":"If someone sallies forth or sallies somewhere, they go out into a rather difficult, dangerous, or unpleasant situation in a brave or confident way.","ex":{"en":"...worrying about her when she sallies forth on her first date","cn":"她第一次赴异性约会时对她的担心"}}]},"examples":[{"en":"Each morning they sallied forth in search of jobs.","cn":"他们每天早上外出找工作。"}]},"sand":{"media":{"uk":"media/uk/sand__gb_1.mp3","us":"media/us/sand__us_1.mp3"},"oxford":{"phon":"sænd","pos":"noun","senses":[{"en":"a substance that consists of very small fine grains of rock. Sand is found on beaches, in deserts, etc.","cn":"沙；沙子","g":"[uncountable]","ex":{"en":"a grain of sand","cn":"一粒沙子"}},{"en":"a large area of sand on a beach or in the desert","cn":"沙滩；沙地；沙漠","g":"[uncountable, countable, usually plural]","ex":{"en":"We went for a walk along the sand.","cn":"我们去沙滩上散了散步。"}},{"en":"to make something smooth by rubbing it with sandpaper or using a sander","cn":"（用砂纸或打磨机）打磨","pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"沙;沙子","en":"Sand is a substance that looks like powder, and consists of extremely small pieces of stone. Some deserts and many beaches are made up of sand.","ex":{"en":"They all walked barefoot across the damp sand to the water's edge.","cn":"他们全都光着脚走过潮湿的沙地来到水边。"}},{"pos":"N-PLURAL 复数名词","cn":"(海滨等的)沙滩","en":"Sands are a large area of sand, for example a beach.","ex":{"en":"...miles of golden sands.","cn":"绵延数英里的金色沙滩"}},{"pos":"VERB 动词","cn":"用砂纸磨光(或擦净)","en":"If you sand a wood or metal surface, you rub sandpaper over it in order to make it smooth or clean.","ex":{"en":"Sand the surface softly and carefully.","cn":"用砂纸仔细而轻柔地打磨表面。"}},{"pos":"PHRASE 短语","cn":"多变;动荡;曲折","en":"If you refer to the shifting sands of a situation, you mean that it changes so often that it is difficult to deal with.","ex":{"en":"He had been a rock in the shifting sands of her existence.","cn":"他一直是她曲折坎坷的生活中的主心骨。"}},{"pos":"","cn":"","en":"相关词组：sand down"}]},"examples":[{"en":"Concrete is a mixture of sand and cement.","cn":"混凝土是沙和水泥的混合物。"},{"en":"We went for a walk along the sand.","cn":"我们去沙滩上散了散步。"}]},"satire":{"oxford":{"phon":"ˈsætaɪə(r)","pos":"noun","senses":[{"en":"a way of criticizing a person, an idea or an institution in which you use humour to show their faults or weaknesses; a piece of writing that uses this type of criticism","cn":"讽刺；讥讽；讽刺作品","ex":{"en":"political/social satire","cn":"政治／社会讽刺作品"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"讽刺;讥讽","en":"Satire is the use of humour or exaggeration in order to show how foolish or wicked some people's behaviour or ideas are.","ex":{"en":"The commercial side of the Christmas season is an easy target for satire.","cn":"圣诞季商业化的一面很容易招来讥讽。"}},{"pos":"N-COUNT 可数名词","cn":"讽刺作品","en":"A satire is a play, film, or novel in which humour or exaggeration is used to criticize something.","ex":{"en":"...a sharp satire on the American political process.","cn":"一部尖刻讽刺美国政治进程的作品"}}]},"media":{"uk":"media/uk/satire__gb_1.mp3","us":"media/us/satire__us_1.mp3"},"examples":[{"en":"The novel is a stinging satire on American politics.","cn":"这部小说是对美国政治的尖锐讽刺。"},{"en":"a work full of savage/biting satire","cn":"一部充满无情/辛辣讽刺的作品"}]},"sarcastic":{"media":{"uk":"media/uk/sarcastic__gb_1.mp3","us":"media/us/sarcastic__us_1.mp3"},"oxford":{"phon":"sɑːˈkæstɪk","pos":"adjective","senses":[{"en":"showing or expressing sarcasm","cn":"讽刺的；嘲讽的；挖苦的","ex":{"en":"sarcastic comments","cn":"冷嘲热讽的话"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"讽刺的;嘲笑的;挖苦的","en":"Someone who is sarcastic says or does the opposite of what they really mean in order to mock or insult someone.","ex":{"en":"She poked fun at people's shortcomings with sarcastic remarks.","cn":"她冷嘲热讽地拿别人的缺点开玩笑。"}}]},"examples":[{"en":"‘There's no need to be sarcastic,’ she said. “","cn":"不必挖苦人嘛。”她说。"},{"en":"‘There's no need to be sarcastic,’ she said.","cn":""}]},"sabbatical":{"media":{"uk":"media/uk/sabbatical__gb_1.mp3","us":"media/us/sabbatical__us_1.mp3"},"oxford":{"phon":"səˈbætɪkl","pos":"noun","senses":[{"en":"a period of time when somebody, especially a teacher at a university, is allowed to stop their normal work in order to study or travel","cn":"（尤指供大学教师进行学术研究或旅行的）公休假，学术休假","ex":{"en":"to take a year’s sabbatical","cn":"休一年的公休假"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(大学教师等的)休假,公休假","en":"A sabbatical is a period of time during which someone such as a university teacher can leave their ordinary work and travel or study.","ex":{"en":"He took a year's sabbatical from the Foreign Office","cn":"他向外交部请了一年的假。"}}]},"examples":[{"en":"He's on sabbatical.","cn":"他正休假。"},{"en":"to take a year's sabbatical","cn":"享受一年的公休假"}]},"said":{"collins":{"senses":[{"pos":"","cn":"","en":"Said is the past tense and past participle of say."}]},"media":{"uk":"media/uk/said__gb_1.mp3","us":"media/us/said__us_1.mp3"},"oxford":{"phon":"sed","pos":"adjective","senses":[{"en":"mentioned before, in an earlier sentence","cn":"前面提到的；上述的","lab":"humorous","ex":{"en":"If you switch to a cheaper company, the said company then raises its prices accordingly.","cn":"如果您转向一家更便宜的公司，该公司就会相应提高价格。"}}]},"base":"say"},"sailing":{"oxford":{"phon":"ˈseɪlɪŋ","pos":"noun","senses":[{"en":"the sport or activity of travelling in a boat with sails","cn":"帆船运动；（乘帆船的）航行","g":"[uncountable]","ex":{"en":"to go sailing","cn":"去进行帆船运动"}},{"en":"one of the regular times that a ship leaves a port","cn":"（从某港口开出的）航班","g":"[countable]","ex":{"en":"There are six sailings a day.","cn":"每天有六班船。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"帆船驾驶;帆船运动","en":"Sailing is the activity or sport of sailing boats.","ex":{"en":"There was swimming and sailing down on the lake.","cn":"有人在湖上游泳和扬帆。"}},{"pos":"N-COUNT 可数名词","cn":"水运航班","en":"Sailings are trips made by a ship carrying passengers.","ex":{"en":"Ferry companies are providing extra sailings from Calais","cn":"渡船公司加开了从加来出发的航班。"}},{"pos":"PHRASE 短语","cn":"轻而易举的;一帆风顺的","en":"If you say that a task was not all plain sailing, you mean that it was not very easy.","ex":{"en":"Pregnancy wasn't all plain sailing and once again there were problems","cn":"孕期并非一帆风顺，这不，又出现问题了。"}}]},"media":{"uk":"media/uk/sailing__gb_1.mp3","us":"media/us/sailing__us_1.mp3","img":["media/ldoce/img/sailboat.jpg"]},"examples":[{"en":"There are six sailings a day.","cn":"每天有六班船。"},{"en":"to go sailing","cn":"去进行帆船运动"}],"base":"sail"},"sandwich":{"oxford":{"phon":"ˈsænwɪtʃ","pos":"noun","senses":[{"en":"two slices of bread, often spread with butter, with a layer of meat, cheese, etc. between them","cn":"三明治","lab":"also British English, informal，，","ex":{"en":"a ham/tuna/egg sandwich","cn":"火腿／金枪鱼／鸡蛋三明治"}},{"en":"a sponge cake consisting of two layers with jam and/or cream between them","cn":"夹心蛋糕","lab":"British English","ex":{"en":"a chocolate sponge sandwich","cn":"巧克力海绵三明治"}},{"en":"a town on the south coast of Kent, England, which was one of the original Cinque Ports. It is now especially famous for its golf course, also called the Royal St George's golf course.","cn":"三明治：位于英国肯特郡南海岸的一个城镇，它是原始的五渔港之一。现在，它以其高尔夫球场而闻名，也称为皇家圣乔治高尔夫球场。","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"三明治;夹心面包片","en":"A sandwich usually consists of two slices of bread with a layer of food such as cheese or meat between them.","ex":{"en":"...a ham sandwich.","cn":"火腿三明治"}},{"pos":"VERB 动词","cn":"夹裹;在…中夹入;把…夹入","en":"If you sandwich two things together with something else, you put that other thing between them. If you sandwich one thing between two other things, you put it between them.","ex":{"en":"Sandwich the two halves of the sponge together with cream","cn":"在两半儿海绵蛋糕中间夹入奶油。"}}]},"media":{"uk":"media/uk/sandwich__gb_1.mp3","us":"media/us/sandwich__us_1.mp3","img":["media/ldoce/img/sandwich.jpg"]},"examples":[{"en":"I was sandwiched between two fat men on the bus.","cn":"在公共汽车上，我被两个胖子挤在中间。"},{"en":"Sandwich the cakes together with cream.","cn":"用奶油把两块蛋糕粘在一起。"}]},"sandy":{"media":{"uk":"media/uk/sandy__gb_1.mp3","us":"media/us/sandy__us_1.mp3"},"oxford":{"phon":"ˈsændi","pos":"adjective","senses":[{"en":"covered with or containing sand","cn":"铺满沙子的；含沙的","ex":{"en":"a sandy beach","cn":"沙滩"}},{"en":"having a light colour, between yellow and red","cn":"沙褐色的；浅棕色的"},{"en":"a first name for boys or girls, short for Alexander, Alexandra, Cassandra or Sandra","cn":"桑迪（男子或女子名，Alexander、Alexandra、Cassandra 或 Sandra 缩写）","pos":""}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"覆盖着沙的;铺满沙的","en":"A sandy area is covered with sand.","ex":{"en":"...long, sandy beaches.","cn":"绵延的沙滩"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（头发）沙土色的，浅黄褐色的，浅棕色的","en":"Sandy hair is light orangey-brown in colour."}]},"examples":[{"en":"sandy soil","cn":"沙质土壤"},{"en":"a sandy beach","cn":"沙滩"}]},"sang":{"lemma":"sing","media":{"uk":"media/uk/sang__gb_1.mp3","us":"media/us/sang__us_1.mp3"}},"sampling":{"oxford":{"phon":"ˈsɑːmplɪŋ","pos":"noun","senses":[{"en":"the process of taking a sample","cn":"抽样；取样","ex":{"en":"statistical sampling","cn":"统计抽样"}},{"en":"the process of copying and recording parts of a piece of music in an electronic form so that they can be used in a different piece of music","cn":"（乐曲的）节录，选录","lab":"specialist"}]},"media":{"uk":"media/uk/sampling__gb_1.mp3","us":"media/us/sampling__us_1.mp3"},"examples":[{"en":"statistical sampling","cn":"统计抽样"}],"base":"sample"},"salts":{"lemma":"salt","media":{"uk":"media/uk/salt__gb_1.mp3","us":"media/us/salt__us_1.mp3"}},"sailor":{"oxford":{"phon":"ˈseɪlə(r)","pos":"noun","senses":[{"en":"a person who works on a ship as a member of the crew","cn":"水手；海员","ex":{"en":"a crew of two officers and 13 sailors","cn":"包括两名船副和 13 名水手的全体船员"}},{"en":"a person who sails a boat","cn":"驾船人","ex":{"en":"My parents were keen sailors.","cn":"我的父母热衷于驾船。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水手;船员;海员","en":"A sailor is someone who works on a ship or sails a boat."}]},"media":{"uk":"media/uk/sailor__gb_1.mp3","us":"media/us/sailor__us_1.mp3"},"examples":[{"en":"Six British sailors drowned.","cn":"六名英国海员溺水身亡。"},{"en":"We were both experienced sailors.","cn":"我们两个都是经验丰富的水手。"}]},"satisfactory":{"media":{"uk":"media/uk/satisfactory__gb_1.mp3","us":"media/us/satisfactory__us_1.mp3"},"oxford":{"phon":"ˌsætɪsˈfæktəri","pos":"adjective","senses":[{"en":"good enough for a particular purpose","cn":"令人满意的；够好的；可以的","ex":{"en":"a satisfactory explanation/answer/solution/conclusion","cn":"令人满意的解释；站得住脚的回答；可行的解决办法；足以服人的结论"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人满意的;恰当的;合适的","en":"Something that is satisfactory is acceptable to you or fulfils a particular need or purpose.","ex":{"en":"I never got a satisfactory answer","cn":"我从未得到令我满意的答复。"}}]},"examples":[{"en":"Her disappearance has never been satisfactorily explained.","cn":"她的失踪一直没有得到令人信服的解释。"},{"en":"Our complaint was dealt with satisfactorily.","cn":"我们的投诉得到了满意的处理。"}]},"sack":{"media":{"uk":"media/uk/sack__gb_1.mp3","us":"media/us/sack__us_1.mp3"},"oxford":{"phon":"sæk","pos":"verb","senses":[{"en":"to dismiss somebody from a job","cn":"解雇；炒鱿鱼","lab":"especially British English, informal，，","ex":{"en":"She was sacked for refusing to work on Sundays.","cn":"她因拒绝在星期天上班被解雇了。"}},{"en":"(of an army, etc., especially in the past) to destroy things and steal property in a town or building","cn":"（尤指旧时军队等）破坏，劫掠","ex":{"en":"Rome was sacked by the Goths in 410.","cn":"罗马在 410 年遭到哥特人的洗劫。"}},{"en":"to knock down the quarterback","cn":"擒杀（四分卫）","ex":{"en":"The quarterback was sacked on the 45 yard line, and it was first down for the other team.","cn":"四分卫在 45 码线上被擒杀，这是对方球队首先被击倒的。"}},{"en":"a large bag with no handles, made of strong rough material or strong paper or plastic, used for storing and carrying, for example flour, coal, etc.","cn":"麻布（或厚纸、塑料等）大袋","g":"[countable]","ex":{"en":"They filled the sacks with potatoes.","cn":"他们将袋子装满了土豆。"},"pos":"noun"},{"en":"a strong paper bag for carrying shopping","cn":"（厚纸的）购物袋","g":"[countable]","lab":"North American English","pos":"noun"},{"en":"the contents of a sack","cn":"一满袋；一大袋东西","g":"[countable]","lab":"North American English","ex":{"en":"They got through a sack of potatoes.","cn":"他们把一麻袋土豆吃完了。"},"pos":"noun"},{"en":"being told by your employer that you can no longer continue working for a company, etc., usually because of something that you have done wrong","cn":"开除；解雇；炒鱿鱼","g":"[singular]","lab":"British English, informal，，","ex":{"en":"He got the sack for swearing.","cn":"他因说脏话而被开除。"},"pos":"noun"},{"en":"a bed","cn":"床","g":"[singular]","lab":"especially North American English, informal，，","ex":{"en":"He caught them in the sack together.","cn":"他撞见他们俩一起睡在床上。"},"pos":"noun"},{"en":"the act of stealing or destroying property in a captured town","cn":"（在攻陷的城镇中的）抢劫，劫掠","g":"[singular]","lab":"formal","ex":{"en":"the sack of Rome","cn":"对罗马城的洗劫"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"麻布袋;粗布袋;厚纸袋;大口袋","en":"A sack is a large bag made of rough woven material. Sacks are used to carry or store things such as vegetables or coal.","ex":{"en":"...a sack of potatoes.","cn":"一袋土豆"}},{"pos":"VERB 动词","cn":"解雇;开除;炒鱿鱼","en":"If your employers sack you, they tell you that you can no longer work for them because you have done something that they did not like or because your work was not good enough.","ex":{"en":"Earlier today the Prime Minister sacked 18 government officials for corruption","cn":"今天早些时候，首相解除了 18 名涉嫌贪污腐败的政府官员的职务。"}},{"pos":"VERB 动词","cn":"抢劫，洗劫，破坏(城镇或城市)","en":"When an army sacks a town or city, they destroy it, taking away all valuable things.","ex":{"en":"In 1527 Imperial troops sacked the French ambassador's residence in Rome.","cn":"1527年，帝国军队洗劫了位于罗马的法国大使官邸。"}},{"pos":"N-SING 单数名词","cn":"床","en":"Some people refer to bed as the sack ."}]},"examples":[{"en":"Rome was sacked by the Goths in 410.","cn":"罗马在 410 年遭到哥特人的洗劫。"},{"en":"She was sacked for refusing to work on Sundays.","cn":"她因拒绝在星期天上班被解雇了。"}]},"saw":{"media":{"uk":"media/uk/saw__gb_1.mp3","us":"media/us/saw__us_1.mp3","img":["media/ldoce/img/saw.jpg"]},"oxford":{"phon":"sɔː","pos":"noun","senses":[{"en":"a tool that has a long blade (= metal cutting part) with sharp points (called teeth) along one of its edges. A saw is moved backwards and forwards by hand or driven by electricity and is used for cutting wood or metal.","cn":"锯"},{"en":"a short phrase or sentence that states a general truth about life or gives advice","cn":"谚语；格言","lab":"old-fashioned","ex":{"en":"As the old saw goes, you can't please all of the people all of the time.","cn":"正如那句老话所说，你不可能一直取悦所有人。"}},{"en":"to use a saw to cut something","cn":"锯","g":"[intransitive, transitive]","ex":{"en":"The workmen sawed and hammered all day.","cn":"工人整天又锯又锤。"},"pos":"verb"},{"en":"to move something backwards and forwards on something as if using a saw","cn":"拉锯似的来回移动（某物）","g":"[intransitive, transitive]","ex":{"en":"She sawed away at her violin.","cn":"她不停地拉着小提琴。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Saw is the past tense of see ."},{"pos":"N-COUNT 可数名词","cn":"锯","en":"A saw is a tool for cutting wood, which has a blade with sharp teeth along one edge. Some saws are pushed backwards and forwards by hand, and others are powered by electricity."},{"pos":"VERB 动词","cn":"锯;用锯割开","en":"If you saw something, you cut it with a saw.","ex":{"en":"He escaped by sawing through the bars of his cell","cn":"他锯断牢房的窗栅栏逃走了。"}}]},"examples":[{"en":"The workmen sawed and hammered all day.","cn":"工人又锯又钉，干了整整一天。"},{"en":"We sawed the wood up into logs.","cn":"我们把木头锯成段段木材。"}],"base":"see"},"salt":{"media":{"uk":"media/uk/salt__gb_1.mp3","us":"media/us/salt__us_1.mp3","img":["media/ldoce/img/salt.jpg"]},"oxford":{"phon":"sɔːlt","pos":"noun","senses":[{"en":"a white substance that is added to food to make it taste better or to preserve it. Salt is obtained from mines and is also found in seawater. It is sometimes called common salt to show that it is different from other chemical salts. Its chemical name is sodium chloride.","cn":"盐，食盐（化学名为“氯化钠”）","g":"[uncountable]","ex":{"en":"Pass the salt, please.","cn":"请把盐递过来。"}},{"en":"a chemical formed from a metal and an acid","cn":"盐（金属和酸组成的化学物质）","g":"[countable]","lab":"chemistry","ex":{"en":"mineral salts","cn":"矿盐"}},{"en":"a substance that looks or tastes like salt","cn":"形状（或味道）像盐的物质","g":"[plural]","ex":{"en":"bath salts (= used to give a pleasant smell to bath water)","cn":"（放在洗澡水中使之芳香的）浴盐"}},{"en":"to put salt on or in food","cn":"在（食物）中放盐","g":"[usually passive]","ex":{"en":"salted peanuts","cn":"咸花生米"},"pos":"verb"},{"en":"to preserve food with salt","cn":"用盐腌制（食物）","ex":{"en":"salted fish","cn":"咸鱼"},"pos":"verb"},{"en":"to put salt on roads to melt ice or snow","cn":"撒盐于（道路）上（以使冰雪融化）","pos":"verb"},{"en":"containing, tasting of or preserved with salt","cn":"含盐的；咸的；用盐腌制的","ex":{"en":"salt water","cn":"海水"},"pos":"adjective"},{"en":"Strategic Arms Limitation Talks","cn":"盐：战略武器限制谈判","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"盐;食盐","en":"Salt is a strong-tasting substance, in the form of white powder or crystals, which is used to improve the flavour of food or to preserve it. Salt occurs naturally in sea water.","ex":{"en":"Season lightly with salt and pepper.","cn":"略微加点盐和胡椒调味。"}},{"pos":"VERB 动词","cn":"给(食物)加盐","en":"When you salt food, you add salt to it.","ex":{"en":"Salt the stock to your taste and leave it simmering very gently.","cn":"根据自己的口味给原汤加点盐，然后用文火慢炖。"}},{"pos":"N-COUNT 可数名词","cn":"盐，盐类(酸和碱的化合物)","en":"Salts are substances that are formed when an acid reacts with an alkali.","ex":{"en":"The rock is rich in mineral salts.","cn":"该岩石中富含矿盐。"}},{"pos":"PHRASE 短语","cn":"人中豪杰;社会中坚;吃苦耐劳的人","en":"If you describe someone as the salt of the earth, you have a lot of respect for them as the type of person who deals with difficult or demanding situations without making any unnecessary fuss.","ex":{"en":"Most of the people there are salt-of-the-earth, good, working-class people.","cn":"那里的大多数人都是吃苦耐劳、心地善良的工人阶级。"}},{"pos":"PHRASE 短语","cn":"对…半信半疑;不完全相信","en":"If you take something with a pinch of salt, you do not believe that it is completely accurate or true.","ex":{"en":"The more miraculous parts of this account should be taken with a pinch of salt.","cn":"对这篇记述中那些颇具神奇色彩的部分也不应全信。"}},{"pos":"PHRASE 短语","cn":"称职;胜任;值得尊敬","en":"If you say, for example, that any doctor worth his or her salt would do something, you mean that any doctor who was good at his or her job or who deserved respect would do it.","ex":{"en":"Any coach worth his salt would do exactly as I did.","cn":"任何称职的教练都会采取和我一模一样的行动。"}},{"pos":"PHRASE 短语","cn":"往伤口上撒盐;雪上加霜;落井下石","en":"If someone or something rubs salt into the wound, they make the unpleasant situation that you are in even worse, often by reminding you of your failures or faults.","ex":{"en":"I had no intention of rubbing salt into a friend's wounds, so all I said was that I did not give interviews.","cn":"我不想往朋友的伤口上撒盐，所以我只说我没有进行面试。"}},{"pos":"","cn":"","en":"相关词组：salt away"}]},"examples":[{"en":"She salted away the profits in foreign bank accounts.","cn":"她把利润偷偷存在外国的银行账户上。"},{"en":"bath salts (= used to give a pleasant smell to bath water) （","cn":"放在洗澡水中使之芳香的）浴盐"}]},"sale":{"media":{"uk":"media/uk/sale__gb_1.mp3","us":"media/us/sale__us_1.mp3"},"oxford":{"phon":"seɪl","pos":"noun","senses":[{"en":"an act or the process of selling something","cn":"出售；销售","g":"[uncountable, countable]","ex":{"en":"regulations governing the sale of alcoholic beverages","cn":"含酒精饮料的销售管理条例"}},{"en":"the number of items sold","cn":"销售量","g":"[plural]","lab":"North American English","ex":{"en":"They have to boost sales to make a profit.","cn":"他们必须提高销量以盈利。"}},{"en":"the part of a company that deals with selling its products","cn":"销售部","g":"[uncountable]","ex":{"en":"a sales and marketing director","cn":"市场销售部经理"}},{"en":"an occasion when a shop or business sells its products at a lower price than usual","cn":"特价销售；廉价出售；大减价","g":"[countable]","ex":{"en":"The sale starts next week.","cn":"特价促销从下星期开始。"}},{"en":"an occasion when goods are sold, especially an auction","cn":"销售活动；（尤指）拍卖","g":"[countable]","ex":{"en":"a contemporary art sale","cn":"当代艺术品拍卖会"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"卖;销售","en":"The sale of goods is the act of selling them for money.","ex":{"en":"Efforts were made to limit the sale of alcohol.","cn":"过去曾采取措施限制酒的销售。"}},{"pos":"N-PLURAL 复数名词","cn":"销售额;销售量","en":"The sales of a product are the quantity of it that is sold.","ex":{"en":"The newspaper has sales of 1.72 million.","cn":"该报纸有 172 万份的销量。"}},{"pos":"N-PLURAL 复数名词","cn":"(公司产品的)销售工作","en":"The part of a company that deals with sales deals with selling the company's products.","ex":{"en":"Until 1983 he worked in sales and marketing","cn":"1983 年之前，他一直在市场营销部工作。"}},{"pos":"N-COUNT 可数名词","cn":"减价出售;大减价;贱卖","en":"A sale is an occasion when a shop sells things at less than their normal price.","ex":{"en":"...a pair of jeans bought half-price in a sale","cn":"打折时半价买的一条牛仔裤"}},{"pos":"N-COUNT 可数名词","cn":"拍卖;拍卖会","en":"A sale is an event when goods are sold to the person who offers the highest price.","ex":{"en":"The painting was bought by dealers at the Christie's sale.","cn":"这幅油画在佳士得的拍卖会上被交易商拍走。"}},{"pos":"PHRASE 短语","cn":"供出售;待售","en":"If something is for sale, it is being offered to people to buy.","ex":{"en":"His former home is for sale at £495,000","cn":"他的旧居要以 49.5 万英镑的价格出售。"}},{"pos":"PHRASE 短语","cn":"出售;上市","en":"Products that are on sale can be bought in shops.","ex":{"en":"English textbooks and dictionaries are on sale everywhere","cn":"英语教材和词典到处都有卖的。"}},{"pos":"PHRASE 短语","cn":"折价销售;减价出售","en":"If products in a shop are on sale, they can be bought for less than their normal price.","ex":{"en":"He bought a sports jacket on sale at Gowings Men's Store.","cn":"他在高英斯男装店买了一件打折的运动上衣。"}},{"pos":"PHRASE 短语","cn":"供出售;待售;转让","en":"If a property or company is up for sale, its owner is trying to sell it.","ex":{"en":"The castle has been put up for sale.","cn":"该城堡已经对外出售。"}}]},"examples":[{"en":"The Weldon Group has a 6 000 strong sales force.","cn":"威尔登集团有 6 000 人的销售队伍。"},{"en":"an increase in the number of stolen vehicles being offered for sale","cn":"用于售卖的被盗车辆在数量上的增加"}]},"salespeople":{"lemma":"salesperson"},"sacrifice":{"media":{"uk":"media/uk/sacrifice__gb_1.mp3","us":"media/us/sacrifice__us_1.mp3"},"oxford":{"phon":"ˈsækrɪfaɪs","pos":"noun","senses":[{"en":"the fact of giving up something important or valuable to you in order to get or do something that seems more important; something that you give up in this way","cn":"牺牲；舍弃","ex":{"en":"The makers of the product assured us that there had been no sacrifice of quality.","cn":"这一产品的制造商向我们保证说他们没有牺牲质量。"}},{"en":"the act of offering something to a god, especially an animal that has been killed in a special way; an animal, etc. that is offered in this way","cn":"祭献；祭祀；祭献的牲畜；祭品","ex":{"en":"They offered sacrifices to the gods.","cn":"他们向众神献上祭品。"}},{"en":"to give up something that is important or valuable to you in order to get or do something that seems more important for yourself or for another person","cn":"牺牲；献出","g":"[transitive]","ex":{"en":"She sacrificed everything for her children.","cn":"她为子女牺牲了一切。"},"pos":"verb"},{"en":"to kill an animal or a person and offer it or them to a god, in order to please the god","cn":"以（人或动物）作祭献","g":"[transitive, intransitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"牺牲;舍弃;献出","en":"If you sacrifice something that is valuable or important, you give it up, usually to obtain something else for yourself or for other people.","ex":{"en":"She sacrificed family life to her career","cn":"她为事业舍弃了家庭。"}},{"pos":"VERB 动词","cn":"献祭;以…为祭品","en":"To sacrifice an animal or person means to kill them in a special religious ceremony as an offering to a god.","ex":{"en":"The priest sacrificed a chicken","cn":"祭司用一只鸡作祭品。"}}]},"examples":[{"en":"The makers of the product assured us that there had been no sacrifice of quality.","cn":"这一产品的制造商向我们保证说他们没有牺牲质量。"},{"en":"Her parents made sacrifices so that she could have a good education.","cn":"为了让她受良好的教育，她的父母作了很多牺牲。"}]},"salads":{"lemma":"salad"},"say":{"media":{"uk":"media/uk/say__gb_1.mp3","us":"media/us/say__us_1.mp3"},"oxford":{"phon":"seɪ","pos":"verb","senses":[{"en":"to speak or tell somebody something, using words","cn":"说；讲；告诉","g":"[intransitive, transitive]","lab":"formal","sc":"speak","ex":{"en":"‘Hello!’ she said.","cn":"“你好！”她说。"}},{"en":"to repeat words, phrases, etc.","cn":"念；朗诵；背诵","g":"[transitive]","sc":"repeat words","ex":{"en":"to say a prayer","cn":"祷告"}},{"en":"to give particular information or instructions","cn":"提供信息；指示","g":"[transitive, no passive]","sc":"give written information","ex":{"en":"The notice said ‘Keep Out’.","cn":"告示上写着“禁止入内”。"}},{"en":"to express an opinion on something","cn":"表达，表述（见解）","g":"[transitive, intransitive]","sc":"express opinion","ex":{"en":"Say what you like (= although you disagree) about her, she's a fine singer.","cn":"随你怎么说，反正她唱歌唱得很好。"}},{"en":"to make thoughts, feelings, etc. clear to somebody by using words, looks, movements, etc.","cn":"表达，表明（思想、感情）","g":"[transitive]","sc":"show thoughts/feelings","ex":{"en":"His angry glance said it all.","cn":"他那愤愤的一瞥就道出了一切。"}},{"en":"to show, sometimes indirectly, what somebody/something is like","cn":"说明；显示","g":"[transitive]","sc":"show what somebody/something is like","ex":{"en":"That says it all really, doesn't it? (= it shows clearly what is true)","cn":"这实际上就说明了一切，是不是？"}},{"en":"to suggest or give something as an example or a possibility","cn":"比方说；假设","g":"[transitive, no passive]","sc":"give example","ex":{"en":"You could learn the basics in, let's say, three months.","cn":"比方说，三个月你就可以掌握基本知识。"}},{"en":"the right to influence something by giving your opinion before a decision is made","cn":"决定权；发言权","ex":{"en":"We had no say in the decision to sell the company.","cn":"在决定出售公司的问题上，我们没有发言权。"},"pos":"noun"},{"en":"used for showing surprise or pleasure","cn":"（表示惊讶或兴奋）嘿，啧啧","ex":{"en":"Say, that's a nice haircut!","cn":"啧啧，这个头发剪得很漂亮！"},"pos":"exclamation"},{"en":"used for attracting somebody’s attention or for making a suggestion or comment","cn":"（提请别人注意、提出建议或作出评论）喂，我说","ex":{"en":"Say, how about going to a movie tonight?","cn":"我说，今晚去看场电影怎么样？"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"说;讲","en":"When you say something, you speak words.","ex":{"en":"'I'm sorry,' he said","cn":"“对不起，”他说。"}},{"pos":"VERB 动词","cn":"(表达观点或陈述事实，否定用法表示婉转暗示某事并非事实)说，表示","en":"You use say in expressions such as I would just like to say to introduce what you are actually saying, or to indicate that you are expressing an opinion or admitting a fact. If you state that you can't say something or you wouldn't say something, you are indicating in a polite or indirect way that it is not the case.","ex":{"en":"I would just like to say that this is the most hypocritical thing I have ever heard in my life","cn":"我只想说这是我这辈子听说过的最虚伪的事情。"}},{"pos":"VERB 动词","cn":"告知;宣称;表明","en":"You can mention the contents of a piece of writing by mentioning what it says or what someone says in it.","ex":{"en":"The report says there is widespread and routine torture of political prisoners in the country","cn":"这份报告称该国一直普遍存在折磨政治犯的现象。"}},{"pos":"VERB 动词","cn":"(自己)想，琢磨;自忖","en":"If you say something to yourself, you think it.","ex":{"en":"Perhaps I'm still dreaming, I said to myself","cn":"也许我还在做梦，我心里想。"}},{"pos":"N-SING 单数名词","cn":"发言权;决定权","en":"If you have a say in something, you have the right to give your opinion and influence decisions relating to it.","ex":{"en":"You can get married at sixteen, and yet you haven't got a say in the running of the country","cn":"你 16 岁时可以结婚，但还无权参与国家政事。"}},{"pos":"VERB 动词","cn":"(钟、刻度盘、地图等)表明，指向，显示","en":"You indicate the information given by something such as a clock, dial, or map by mentioning what it says .","ex":{"en":"The clock said four minutes past eleven","cn":"钟显示时间是 11 点 4 分。"}},{"pos":"VERB 动词","cn":"说明;表明;表示","en":"If something says something about a person, situation, or thing, it gives important information about them.","ex":{"en":"I think that says a lot about how well Seles is playing","cn":"我认为那很能说明塞勒斯表现得有多出色。"}},{"pos":"VERB 动词","cn":"说明，表示(…有很多优点)","en":"If something says a lot for a person or thing, it shows that this person or thing is very good or has a lot of good qualities.","ex":{"en":"It says a lot for him that he has raised his game to the level required","cn":"他将比赛技能提至所要求的水平，这说明他颇有能耐。"}},{"pos":"VERB 动词","cn":"(通常表示说话者认为某人优点不多)我会这样形容他们/你可以这样形容他们","en":"You use say in expressions such as I'll say that for them and you can say this for them after or before you mention a good quality that someone has, usually when you think they do not have many good qualities.","ex":{"en":"He's usually smartly-dressed, I'll say that for him","cn":"我能说的是，至少他通常穿着入时。"}},{"pos":"VERB 动词","cn":"假定;假设","en":"You can use say when you want to discuss something that might possibly happen or be true.","ex":{"en":"Say you could change anything about the world we live in, what would it be?","cn":"假定你能对我们所生活的这个世界作出任意改变，你会改变什么呢？"}},{"pos":"","cn":"比如说;比方说","en":"You can use say or let's say when you mention something as an example.","ex":{"en":"To see the problem here more clearly, let's look at a different biological system, say, an acorn","cn":"为更清晰地理解此处的问题，我们来看一种不同的生物系统，比如说，橡子。"}},{"pos":"EXCLAM 感叹语","cn":"(用以唤起注意或表示惊讶、高兴、崇敬)嘿，喂，哎呀，啊","en":"Say is used to attract someone's attention or to express surprise, pleasure, or admiration.","ex":{"en":"Say, Leo, how would you like to have dinner one night, just you and me?","cn":"哎，利奥，找个晚上一起吃顿饭如何，就你和我？"}},{"pos":"PHRASE 短语","cn":"清楚说明事实;明确表达(…的)感觉","en":"If you say that something says it all, you mean that it shows you very clearly the truth about a situation or someone's feelings.","ex":{"en":"This is my third visit in a week, which says it all.","cn":"这是我一周内第3次拜访，这说明了一切。"}},{"pos":"CONVENTION 惯用语","cn":"(表示吃惊)不会吧;(亦常表示事实上并不吃惊)我一点也不觉得奇怪，用不着你说也知道","en":"You can use 'You don't say' to express surprise at what someone has told you. People often use this expression to indicate that in fact they are not surprised.","ex":{"en":"'I'm a writer.' — 'You don't say. What kind of book are you writing?'","cn":"“我是作家。”——“不会吧。你写哪方面的书？”"}},{"pos":"PHRASE 短语","cn":"值得称道之处;优点","en":"If you say there is a lot to be said for something, you mean you think it has a lot of good qualities or aspects.","ex":{"en":"There's a lot to be said for being based in the country.","cn":"把总部设在该国有很多优势。"}},{"pos":"PHRASE 短语","cn":"寡言少语;不爱说话","en":"If you say that someone doesn't have much to say for himself or herself, you mean that they are not speaking very much during a conversation.","ex":{"en":"He's never got much to say for himself.","cn":"他向来寡言少语。"}},{"pos":"PHRASE 短语","cn":"你有什么好说的;你有什么要辩解的","en":"If someone asks what you have to say for yourself, they are asking what excuse you have for what you have done.","ex":{"en":"'Well,' she said eventually, 'what have you to say for yourself?'","cn":"“那么”，她最后说，“你有什么好说的？”"}},{"pos":"PHRASE 短语","cn":"显而易见;不言而喻;不用说","en":"If something goes without saying, it is obvious.","ex":{"en":"It goes without saying that if someone has lung problems they should not smoke.","cn":"不用说，有肺病的人不应吸烟。"}},{"pos":"PHRASE 短语","cn":"发表意见;阐述观点","en":"When one of the people or groups involved in a discussion has their say, they give their opinion.","ex":{"en":"The Football Association have had their say.","cn":"足协已经发表了意见。"}},{"pos":"PHRASE 短语","cn":"(用于对很多人不喜欢的人或事物表示赞赏时)随你怎么说,不管你怎么认为","en":"You use 'Say what you like about someone or something' when you are about to mention one good thing about a person or thing that many people do not like.","ex":{"en":"Say what you like about them, but they did love their Mum.","cn":"随你怎么说，但他们确实爱自己的妈妈。"}},{"pos":"CONVENTION 惯用语","cn":"(尤指乐于接受他人刚刚提出要给予自己的东西)我不反对，我没意见，好哇","en":"You use 'I wouldn't say no' to indicate that you would like something, especially something that has just been offered to you.","ex":{"en":"I wouldn't say no to a drink.","cn":"我倒想喝一杯。"}},{"pos":"PHRASE 短语","cn":"(引出语气更重或更极端的描述)即使不说是…,虽不能说…","en":"You can use not to say when adding a stronger or more extreme description than the one you have just used.","ex":{"en":"To those who've never received million dollar royalty cheques, this sounded a little odd, not to say offensive.","cn":"对于那些从没有收到过上百万美元版权费的人来说，这听起来就算不令人反感，至少也让人觉得有点儿怪。"}},{"pos":"PHRASE 短语","cn":"更不用说;何况","en":"You use to say nothing of when you mention an additional thing which gives even more strength to the point you are making.","ex":{"en":"Unemployment leads to a sense of uselessness, to say nothing of financial problems.","cn":"失业会让人觉得自己一无是处，更何况还会带来经济问题。"}},{"pos":"PHRASE 短语","cn":"(用于提醒别人所说话可能会具有冒犯性或令人震惊)可以说","en":"You use shall I say and shall we say in order to warn someone that what you are about to say may cause offence or be surprising.","ex":{"en":"...whereas when you get older you're rather set in your ways, shall I say","cn":"然而随着年纪渐长，可以说，你的大局已定了。"}},{"pos":"PHRASE 短语","cn":"亦即;也就是说;换句话说","en":"You use that is to say or that's to say to indicate that you are about to express the same idea more clearly or precisely.","ex":{"en":"...territories that were occupied in 1967, that is to say, in the West Bank and Gaza.","cn":"1967年被占的领土，也就是约旦河西岸和加沙地带的被占领土"}},{"pos":"CONVENTION 惯用语","cn":"让你说对了;一点没错;我同意;说得太对了","en":"You can use 'You can say that again' to express strong agreement with what someone has just said.","ex":{"en":"'Must have been a fiddly job.' — 'You can say that again.'","cn":"“那一定是件精细活。”——“说得太对了。”"}},{"pos":"","cn":"","en":"to say the least→see: ; needless to say→see: ;"}]},"examples":[{"en":"I sometimes get worried in this job. Having said that, I enjoy doing it, it's a challenge.","cn":"我有时会为这份工作而感到忧虑。话虽如此，我还是满喜欢干的，因为这是一个挑战。"},{"en":"‘I know I'm not the world's greatest cook.’ ‘You said it!’ “","cn":"我知道我的饭菜做得不是太好。” “这话可是你说的！”"}]},"sa":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"South Africa","cn":"南非"}]}},"salaries":{"lemma":"salary","media":{"uk":"media/uk/salary__gb_1.mp3","us":"media/us/salary__us_1.mp3"}},"sabotage":{"media":{"uk":"media/uk/sabotage__gb_1.mp3","us":"media/us/sabotage__us_1.mp3"},"oxford":{"phon":"ˈsæbətɑːʒ","pos":"noun","senses":[{"en":"the act of doing deliberate damage to equipment, transport, machines, etc. to prevent an enemy from using them, or to protest about something","cn":"（为防止敌人利用或表示抗议而对设备、交通等进行的）蓄意毁坏，人为破坏","ex":{"en":"an act of economic/military/industrial sabotage","cn":"经济／军事／工业破坏活动"}},{"en":"the act of preventing something from being successful or being achieved, especially deliberately","cn":"（尤指刻意的）阻碍，妨碍，捣乱"},{"en":"to damage or destroy something deliberately to prevent an enemy from using it or to protest about something","cn":"蓄意破坏（以防止敌方利用或表示抗议）","ex":{"en":"The main electricity supply had been sabotaged by the rebels.","cn":"叛乱者破坏了供电干线。"},"pos":"verb"},{"en":"to prevent something from being successful or being achieved, especially deliberately","cn":"刻意阻碍；妨碍；捣乱","ex":{"en":"Protesters failed to sabotage the peace talks.","cn":"抗议者未能破坏和平谈判。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"蓄意破坏，阴谋摧毁(机器、铁路、桥梁)","en":"If a machine, railway line, or bridge is sabotaged, it is deliberately damaged or destroyed, for example in a war or as a protest.","ex":{"en":"The main pipeline supplying water was sabotaged by rebels.","cn":"供水主管道被叛乱分子蓄意破坏了。"}},{"pos":"VERB 动词","cn":"阻挠,妨碍,暗中破坏(计划的实施或会议的进行)","en":"If someone sabotages a plan or a meeting, they deliberately prevent it from being successful.","ex":{"en":"He accused the opposition of trying to sabotage the election","cn":"他谴责反对派企图阻挠选举的进行。"}}]},"examples":[{"en":"Police investigating the train derailment have not ruled out sabotage.","cn":"警方调查火车出轨事件，没有排除人为破坏的可能。"},{"en":"The rise in interest rates sabotaged any chance of the firm's recovery.","cn":"由于利率的提高，公司的复苏已无任何可能。"}]},"says":{"lemma":"say"},"sales":{"lemma":"sale"},"sacks":{"lemma":"sack"},"salons":{"lemma":"salon"},"savor":{"oxford":{"phon":"ˈseɪvə(r)","pos":"verb","senses":[{"en":"to enjoy the full taste or flavour of sth, especially by eating or drinking it slowly","cn":"品味；细品；享用"},{"en":"to enjoy a feeling or an experience thoroughly","cn":"体会；体味；享受"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld5_savor.mp3","us":"media/ldoce/hwd/ame/d/ld5_savor.mp3"}},"sands":{"lemma":"sand"},"saves":{"lemma":"save"},"santa":{"oxford":{"phon":"ˈsæntə klɔːz","pos":"noun","senses":[{"en":"an imaginary old man with red clothes and a long white beard. Parents tell small children that he brings them presents at Christmas.","cn":"圣诞老人"}]}},"saved":{"lemma":"save"},"samples":{"lemma":"sample"},"sandals":{"lemma":"sandal","media":{"img":["media/ldoce/img/sandals.jpg"]}},"salesman":{"oxford":{"phon":"ˈseɪlzmən","pos":"noun","senses":[{"en":"a man whose job is to sell goods, for example, in a shop","cn":"推销员;售货员","lab":"British English","ex":{"en":"a car salesman","cn":"汽车推销员"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男店员;男售货员;男推销员","en":"A salesman is a man whose job is to sell things, especially directly to shops or other businesses on behalf of a company.","ex":{"en":"...an insurance salesman.","cn":"保险推销员"}}]},"media":{"uk":"media/ldoce/hwd/bre/f/salesman0205.mp3","us":"media/ldoce/hwd/ame/d/salesman.mp3"}},"saxophones":{"oxford":{"phon":"ˈsæksəfəʊn","pos":"noun","senses":[{"en":"a metal musical instrument that you blow into, used especially in jazz","cn":"萨克斯管； （台）萨克斯风"}]}},"satellites":{"lemma":"satellite"},"sahara":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the world's largest desert which covers a very large area of North Africa. Some scientists believe that the desert is gradually becoming bigger.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/p028-000010736.mp3","us":"media/ldoce/hwd/ame/d/p028-000010736.mp3"}},"salzburg":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a city in Austria famous for the music festival that takes place there every year, and for being the place where mozart was born","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/p028-000010781.mp3","us":"media/ldoce/hwd/ame/c/p028-000010781.mp3"}},"sabbath":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"安息日(犹太教的安息日是星期六，基督教的安息日是星期日)","en":"The Sabbath is the day of the week when members of some religious groups do not work. The Jewish Sabbath is on Saturday and the Christian Sabbath is on Sunday.","ex":{"en":"...a religious man who kept the Sabbath","cn":"过安息日的教徒"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"Sunday, considered as a day of rest and prayer by most Christian churches","cn":"安息日〔星期日﹐大多数基督教会认为应当休息和祈祷的日子〕"},{"en":"Saturday, considered as a day of rest and prayer in the Jewish religion and some Christian churches","cn":"安息日〔星期六﹐犹太教以及一些基督教会认为应当休息和祈祷的日子〕"},{"en":"to obey or not obey the religious rules of the Sabbath","cn":"守/不守安息日"}]},"collocations":{"phrases":["ADJ. Jewish, Muslim, etc.","VERB + SABBATH keep, observe | break","SABBATH + NOUN day | rest","PREP. on the ~ It was considered a sin to work or play on the Sabbath.","PHRASES observance of the Sabbath The speaker advocated a less austere observance of the Sabbath."]},"media":{"uk":"media/ldoce/hwd/bre/2/sabbath0205.mp3","us":"media/ldoce/hwd/ame/5/sabbath.mp3"},"examples":[{"en":"to keep/break the Sabbath (= to obey/not obey the religious rules for this day)","cn":"守/不守安息日"}],"oxford":{"phon":"ˈsæbəθ","pos":"noun","senses":[{"en":"the holy day of the week that is used for resting and worshipping God. For Jewish people this day is Saturday and for Christians it is Sunday.","cn":"安息日（犹太教定为星期六，基督教定为星期日）","ex":{"en":"to keep/break the Sabbath (= to obey/not obey the religious rules for this day)","cn":"守／不守安息日"}}]}},"sanctuary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"避难所;庇护所;躲避处","en":"A sanctuary is a place where people who are in danger from other people can go to be safe.","ex":{"en":"His church became a sanctuary for thousands of people who fled the civil war.","cn":"他的教堂成为成千上万逃离内战的人们的避难所。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"避难;庇护","en":"Sanctuary is the safety provided in a sanctuary.","ex":{"en":"Some of them have sought sanctuary in the church.","cn":"他们中的一些人在教堂避难。"}},{"pos":"N-COUNT 可数名词","cn":"禁猎区;鸟兽保护区","en":"A sanctuary is a place where birds or animals are protected and allowed to live freely.","ex":{"en":"...a bird sanctuary.","cn":"鸟类禁猎区"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if someone or something is out of harm's way , they are in a place where they cannot be hurt or damaged","cn":""},{"en":"a place where you are safe from danger","cn":""},{"en":"a place where you can go in order to escape from a dangerous or unpleasant situation","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The word sanctuary has religious roots, and can refer to a temple or church, but its use has broadened to include anywhere people go for peaceful tranquility or introspection. Your pickup truck might be your sanctuary if that's where you can clear your head."}]},"collocations":{"phrases":["VERB + SANCTUARY seek Thousands of refugees have sought sanctuary in neighbouring countries. | take In former times, criminals could take sa","PREP. ~ from It had been built as a sanctuary from World War II bombs."]},"media":{"uk":"media/ldoce/hwd/bre/f/sanctuary0205.mp3","us":"media/ldoce/hwd/ame/4/sanctuary.mp3"},"examples":[{"en":"The government offered sanctuary to 4 000 refugees.","cn":"政府为 4 000 名难民提供了保护。"},{"en":"She longed for the sanctuary of her own home.","cn":"她渴望回到自己家中，不再担惊受怕。"}],"oxford":{"phon":"ˈsæŋktʃuəri","pos":"noun","senses":[{"en":"an area where wild birds or animals are protected and encouraged to produce young","cn":"鸟兽保护区；禁猎区","g":"[countable]","ex":{"en":"a bird/wildlife sanctuary","cn":"鸟类／野生动物保护区"}},{"en":"safety and protection, especially for people who are in danger of being attacked or captured","cn":"庇护；保护","g":"[uncountable]","ex":{"en":"to seek/find/take sanctuary in a place","cn":"在某处寻找／找到庇护；在某处避难"}},{"en":"a safe place, especially one where people who are in danger of being attacked or captured can stay and be protected","cn":"避难所；庇护所","g":"[countable, usually singular]","ex":{"en":"The church became a sanctuary for the refugees.","cn":"教堂成为这些难民的庇护所。"}},{"en":"a holy building or the part of it that is considered the most holy","cn":"圣所；圣殿","g":"[countable]","ex":{"en":"the sanctuary of Poseidon at Sourvion","cn":"苏维翁 (Sourvion) 的波塞冬圣殿"}}]}},"salon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"美容院;美发厅;发廊","en":"A salon is a place where people have their hair cut or coloured, or have beauty treatments.","ex":{"en":"...a new hair salon.","cn":"新开的美发厅"}},{"pos":"N-COUNT 可数名词","cn":"高级服装店;时装店","en":"A salon is a shop where smart, expensive clothes are sold."},{"pos":"N-COUNT 可数名词","cn":"(旧时较为流行的)文艺界名流聚会，雅集，文艺沙龙","en":"A salon is an informal meeting of fashionable writers or artists, which is held at the house of someone who is well-known. Salons were more common in former times.","ex":{"en":"His apartment was the most famous literary salon in Russia.","cn":"他的公寓是俄国最著名的文学沙龙会所。"}},{"pos":"N-COUNT 可数名词","cn":"(豪华住宅的)客厅,会客室","en":"A salon is a sitting room in a large, grand house."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building or place where things are sold","cn":""},{"en":"a small shop that sells fashionable clothes or other objects","cn":""},{"en":"a very large shop, especially one that is built outside the centre of a city","cn":""}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"Use the noun salon when you talk about the place you get your hair cut. A salon is a good place to get a perm or highlights, to get your nails painted, or just to get a trim."}]},"collocations":{"phrases":["ADJ. beauty, grooming, hair, hairdressing | leading, professional, top | unisex","VERB + SALON go to"]},"media":{"uk":"media/ldoce/hwd/bre/b/salon0205.mp3","us":"media/ldoce/hwd/ame/3/salon.mp3"},"examples":[{"en":"a literary salon","cn":"文艺沙龙"},{"en":"a beauty salon","cn":"美容厅"}],"oxford":{"phon":"ˈsælɒn","pos":"noun","senses":[{"en":"a shop that gives customers hair or beauty treatment or that sells expensive clothes","cn":"美发厅；美容院；高级服装店","ex":{"en":"a beauty salon","cn":"美容院"}},{"en":"a room in a large house used for entertaining guests","cn":"（大宅中的）客厅，会客室","lab":"old-fashioned"},{"en":"(in the past) a regular meeting of writers, artists and other guests at the house of a famous or important person","cn":"沙龙（旧时作家、艺术家等在名流家中定期举行的聚会）","ex":{"en":"a literary salon","cn":"文艺沙龙"}}]}},"saviour":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"救助者;拯救者;救星","en":"A saviour is a person who saves someone or something from danger, ruin, or defeat.","ex":{"en":"...the saviour of his country.","cn":"他的国家的救星"}},{"pos":"N-PROPER 专有名词","cn":"救主，救世主(基督教中对耶稣基督的称谓)","en":"In the Christian religion, the Saviour is Jesus Christ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who saves you from a difficult or dangerous situation","cn":"救助者﹐挽救者﹐救星"}]},"collocations":{"phrases":["ADJ. possible, potential","VERB + SAVIOUR hail sb as, see sb/sth as, treat sb as The people clearly saw her as their saviour. | be acclaimed as, emerge as He emerged a"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdesaviour.mp3","us":"media/ldoce/hwd/ame/2/savior.mp3"},"examples":[{"en":"The new manager has been hailed as the saviour of the club.","cn":"新任经理被誉为俱乐部的救星。"},{"en":"He was seen by many as the saviour of the organization.","cn":"他被许多人看作该组织的救星。"}],"oxford":{"phon":"ˈseɪvjə(r)","pos":"noun","senses":[{"en":"a person who rescues somebody/something from a dangerous or difficult situation","cn":"救助者；拯救者；救星","g":"[usually singular]","ex":{"en":"The new manager has been hailed as the saviour of the club.","cn":"新任主教练被誉为俱乐部的救星。"}},{"en":"used in the Christian religion as another name for Jesus Christ","cn":"救主，救世主（耶稣基督）","g":"[singular]"}]}},"sanction":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(正式)认可，准许，批准","en":"If someone in authority sanctions an action or practice, they officially approve of it and allow it to be done.","ex":{"en":"He may now be ready to sanction the use of force","cn":"他现在可能打算批准使用武力。"}},{"pos":"N-PLURAL 复数名词","cn":"(对某国的)制裁","en":"Sanctions are measures taken by countries to restrict trade and official contact with a country that has broken international law.","ex":{"en":"In 1935 the League of Nations imposed sanctions against Italy following its invasion of Ethiopia.","cn":"1935 年国际联盟在意大利入侵埃塞俄比亚之后对其实施了制裁。"}},{"pos":"N-COUNT 可数名词","cn":"处罚;制裁;惩罚","en":"A sanction is a severe course of action which is intended to make people obey instructions, customs, or laws.","ex":{"en":"As an ultimate sanction, they can sell their shares.","cn":"作为最高的处罚，他们可以出售他们的股份。"}},{"pos":"VERB 动词","cn":"对…实施制裁;处罚","en":"If a country or an authority sanctions another country or a person for doing something, it declares that the country or person is guilty of doing it and imposes sanctions on them.","ex":{"en":"...their failure to sanction Japan for butchering whales in violation of international conservation treaties.","cn":"对日本违反国际保护条约残杀鲸鱼的行为他们未能进行制裁"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official statement that forbids something, based on a law or a government decision","cn":""},{"en":"official orders forbidding trade or dealings with a particular country, used as a way of punishing them or stopping them from doing something","cn":""},{"en":"an official order forbidding trade in a particular product with a particular country for political or economic reasons","cn":""}]},"vocab":{"pos":"1 n v 2 n v","senses":[{"en":"Sanction has two nearly opposite meanings: to sanction can be to approve of something, but it can also mean to punish, or speak harshly to. Likewise, a sanction can be a punishment or approval. Very confusing––the person who invented this word should be publicly sanctioned!"}]},"collocations":{"phrases":["ADJ. official | divine, religious","VERB + SANCTION give sb/sth The conference gave its official sanction to the change of policy.","PREP. with/without sb/sth's ~ No decision can be taken without the sanction of the complete committee. 2 punishment","ADJ. heavy, severe, strict | final, ultimate | effective | limited | available The school will use all available sanctions to maintain disci","VERB + SANCTION impose | use","PREP. ~ against There were strict sanctions against absenteeism. | ~ for Employers imposed heavy sanctions for union activity. 3 (usually sa","ADJ. punitive | international, UN | economic, financial, military, trade","VERB + SANCTION impose | lift | break Some companies have broken sanctions by supplying arms to the warring states. | call for"]},"media":{"uk":"media/ldoce/hwd/bre/7/sanction_v0205.mp3","us":"media/ldoce/hwd/ame/a/sanction1.mp3"},"examples":[{"en":"Trade sanctions were imposed against any country that refused to sign the agreement.","cn":"凡拒签该协议的国家均受到贸易制裁。"},{"en":"The ultimate sanction will be the closure of the restaurant.","cn":"最严厉的处罚将是关闭这家餐馆。"}],"oxford":{"phon":"ˈsæŋkʃn","pos":"noun","senses":[{"en":"an official order that limits trade, contact, etc. with a particular country, in order to make it do something, such as obeying international law","cn":"制裁","g":"[countable, usually plural]","lab":"US English","ex":{"en":"Trade sanctions were imposed against any country that refused to sign the agreement.","cn":"凡拒签该协议的国家均受到贸易制裁。"}},{"en":"official permission or approval for an action or a change","cn":"（正式）许可，批准","g":"[uncountable]","lab":"formal","ex":{"en":"These changes will require the sanction of the court.","cn":"这些变更须经法院认可。"}},{"en":"a course of action that can be used, if necessary, to make people obey a law or behave in a particular way","cn":"制裁；约束；处罚","g":"[countable]","ex":{"en":"The ultimate sanction will be the closure of the restaurant.","cn":"最严厉的处罚将是关闭这家餐馆。"}},{"en":"to give permission for something to take place","cn":"许可；准许；准予","lab":"formal","ex":{"en":"The government refused to sanction a further cut in interest rates.","cn":"政府拒绝批准进一步降低利率。"},"pos":"verb"},{"en":"to punish somebody/something; to impose a sanction on something","cn":"惩罚；实施制裁","lab":"specialist","pos":"verb"}]}},"salvation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"灵魂的得救;超度;救赎","en":"In Christianity, salvation is the fact that Christ has saved a person from evil.","ex":{"en":"The church's message of salvation has changed the lives of many.","cn":"基督教中耶稣拯救灵魂的教义改变了很多人的生活。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"解救;拯救","en":"The salvation of someone or something is the act of saving them from harm, destruction, or an unpleasant situation.","ex":{"en":"...a poor, lost, lonely woman clinging for salvation to a son whom she knew was as lost as she was.","cn":"一个孤独可怜、茫然若失的妇人紧紧抓着她的一个儿子寻求解脱，而她知道儿子也同她一样迷惘"}},{"pos":"N-SING 单数名词","cn":"拯救者;救星;解救物","en":"If someone or something is your salvation, they are responsible for saving you from harm, destruction, or an unpleasant situation.","ex":{"en":"The country's salvation lies in forcing through democratic reforms","cn":"拯救国家的希望在于强制推行民主改革。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that prevents or saves someone or something from danger, loss, or failure","cn":"解救物﹔救星﹐救助者"},{"en":"in the Christian religion, the state of being saved from evil 〔","cn":"基督教中〕灵魂的拯救﹐救赎"}]},"vocab":{"pos":"n","senses":[{"en":"Salvation is the act of saving from sin or evil, or sometimes just from an unpleasant situation."}]},"collocations":{"phrases":["ADJ. individual, personal | eternal","VERB + SALVATION bring | seek | attain, find | work out I can't solve her problems for her?she'll have to work out her own salvation.","PREP. ~ from salvation from sin | ~ through The medieval Church believed in salvation through faith and works."]},"media":{"uk":"media/ldoce/hwd/bre/0/salvation_las2_br.mp3","us":"media/ldoce/hwd/ame/0/salvation.mp3"},"examples":[{"en":"Group therapy classes have been his salvation.","cn":"他一直靠参加集体疗法班来调节心理。"},{"en":"to pray for the salvation of the world","cn":"为世人得救而祷告"}],"oxford":{"phon":"sælˈveɪʃn","pos":"noun","senses":[{"en":"a way of protecting somebody from danger, disaster, loss, etc.","cn":"（危险、灾难、损失等的）避免方式，解救途径","ex":{"en":"Group therapy classes have been his salvation.","cn":"他一直靠参加集体治疗小组来调节心理。"}},{"en":"the state of being saved from the power of evil","cn":"得救；救恩；救世","ex":{"en":"to pray for the salvation of the world","cn":"为世人得救而祷告"}}]}},"safeguard":{"collins":{"senses":[{"pos":"VERB 动词","cn":"保护;保卫;维护;捍卫","en":"To safeguard something or someone means to protect them from being harmed, lost, or badly treated.","ex":{"en":"They will press for international action to safeguard the ozone layer","cn":"他们将督促国际社会采取行动保护臭氧层。"}},{"pos":"N-COUNT 可数名词","cn":"预防性条款(或法规);保障措施","en":"A safeguard is a law, rule, or measure intended to prevent someone or something from being harmed.","ex":{"en":"Many people took second jobs as a safeguard against unemployment","cn":"许多人为防失业都干两份工作。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to keep someone or something safe from harm, damage, or illness","cn":""},{"en":"to protect someone from something harmful","cn":""},{"en":"to protect a person, place, or object by staying near them and watching them","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A safeguard is a defense or precaution. You could describe a flu shot as a safeguard against getting sick, for example."}]},"collocations":{"phrases":["ADJ. adequate, effective, proper, sufficient Does the procedure provide adequate safeguards against corruption? | added, additional, extra, ","VERB + SAFEGUARD introduce | provide (sb with) | build in/into sth Appropriate safeguards would have to be built into the procedures to avoi","PREP. ~ against The credit agreement includes safeguards against overcharging."]},"media":{"uk":"media/ldoce/hwd/bre/9/safeguard_v0205.mp3","us":"media/ldoce/hwd/ame/e/safeguard1.mp3"},"examples":[{"en":"The leaflet explains how to safeguard against dangers in the home.","cn":"小册子告诉人们在家里如何防备各种危险。"},{"en":"Stronger legal safeguards are needed to protect the consumer.","cn":"需要有更有力的法律措施来保护消费者。"}],"oxford":{"phon":"ˈseɪfɡɑːd","pos":"verb","senses":[{"en":"to protect something/somebody from loss, harm or damage; to keep something/somebody safe","cn":"保护；保障；捍卫","ex":{"en":"to safeguard a person’s interests","cn":"维护某人的利益"}},{"en":"something that is designed to protect people from harm, risk or danger","cn":"安全设施；保护措施","ex":{"en":"Stronger legal safeguards are needed to protect the consumer.","cn":"需要有更有力的法律措施来保护消费者。"},"pos":"noun"}]}},"sausage":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"香肠;腊肠","en":"A sausage consists of minced meat, usually pork, mixed with other ingredients and is contained in a tube made of skin or a similar material.","ex":{"en":"...sausages and chips.","cn":"香肠和薯条"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small tube of skin filled with a mixture of meat, spices etc, eaten hot or cold after it has been cooked","cn":"香肠"},{"en":"nothing at all","cn":"一点儿也没有！"}]},"collocations":{"phrases":["ADJ. beef, garlic, liver, pork, etc. | vegetarian | spicy","QUANT. slice","VERB + SAUSAGE eat, have | cook, fry, grill","SAUSAGE + VERB sizzle","SAUSAGE + NOUN meat, skin | roll •"]},"media":{"uk":"media/ldoce/hwd/bre/3/sausage_las2_br.mp3","us":"media/ldoce/hwd/ame/0/sausage.mp3"},"examples":[{"en":"200g of garlic sausage * 200","cn":"克蒜味香肠"},{"en":"beef/pork sausages","cn":"牛肉/猪肉香肠"}],"oxford":{"phon":"ˈsɒsɪdʒ","pos":"noun","senses":[{"en":"a mixture of meat, fat, bread, etc. cut into small pieces, put into a long tube of skin, cooked and eaten whole or served cold in thin slices","cn":"香肠；腊肠","ex":{"en":"beef/pork sausages","cn":"牛肉／猪肉香肠"}}]}},"saga":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"长篇小说;长篇故事;一连串事件","en":"A saga is a long story, account, or sequence of events.","ex":{"en":"...a 600 page saga about 18th century slavery.","cn":"关于 18 世纪奴隶制的总计 600 页的长篇记述"}},{"pos":"N-COUNT 可数名词","cn":"萨迦(中世纪挪威或冰岛的传奇故事)","en":"A saga is a long story composed in medieval times in Norway or Iceland.","ex":{"en":"...a Nordic saga of giants and trolls.","cn":"一篇关于巨人和山精的北欧萨迦"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a description of how something happened that is intended to entertain people, and may be true or imaginary","cn":""},{"en":"a story about strange imaginary events, or exciting events that happened in the past","cn":""},{"en":"a very old imaginary story about gods and magical creatures","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When your friend tells you every detail of how she tripped over a rock, broke her ankle, and then got into a car accident on the way to the hospital, she is sharing a long, involved story known as a saga ."}]},"collocations":{"phrases":["ADJ. continuing, long-running, ongoing | extraordinary | sorry, terrible | complicated | family","PREP. in a/the ~ His suicide is the latest chapter in this terrible saga of greed and betrayal."]},"media":{"uk":"media/ldoce/hwd/bre/3/saga0205.mp3","us":"media/ldoce/hwd/ame/3/saga.mp3"},"examples":[{"en":"( humorous ) the saga of how I missed the plane","cn":"有关我如何误了飞机的一连串倒霉事儿"},{"en":"The front page is devoted to the continuing saga of the hijack.","cn":"头版是对劫持事件的连续报道。"}],"oxford":{"phon":"ˈsɑːɡə","pos":"noun","senses":[{"en":"a long traditional story about adventures and brave acts, especially one from Norway or Iceland","cn":"萨迦（尤指古代挪威或冰岛讲述冒险经历和英雄事迹的长篇故事）"},{"en":"a long story about events over a period of many years","cn":"（讲述许多年间发生的事情的）长篇故事，长篇小说","ex":{"en":"a family saga","cn":"家世小说"}},{"en":"a long series of events or adventures and/or a report about them","cn":"一连串的事件（或经历）；一连串经历的讲述（或记述）","lab":"humorous","ex":{"en":"The front page is devoted to the continuing saga of the hijack.","cn":"头版是对劫持事件的连续报道。"}},{"en":"a British travel company started in the 1950s which organizes and sells holidays for people aged over 50. The company also provides financial services for older people and publishes a magazine.","cn":"一家成立于1950年代的英国旅行公司，为50岁以上的人们组织和销售假期。该公司还为老年人提供金融服务，并出版一本杂志。","pos":""}]}},"saucepan":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(有盖、长柄、较深的)炖锅;深平底锅","en":"A saucepan is a deep metal cooking pot, usually with a long handle and a lid.","ex":{"en":"Cook the potatoes and turnips in a large saucepan.","cn":"用大炖锅煮土豆和芜菁。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a deep round metal container with a handle that is used for cooking 〔","cn":"有柄的〕深平底锅"}]},"collocations":{"phrases":["ADJ. non-stick | heavy, heavy-based","VERB + SAUCEPAN cover Cover the saucepan and remove from the heat. | remove from the heat | add sth to, put sth in/into, return sth to | rem","SAUCEPAN + VERB contain sth a pan containing lots of boiling salted water","PREP. in/into a/the ~ Heat one tablespoon of oil in a saucepan. Pour the pasta into a pan of boiling water."]},"media":{"img":["media/ldoce/img/saucepan.jpg"],"uk":"media/ldoce/hwd/bre/1/saucepan0205.mp3","us":"media/ldoce/hwd/ame/3/saucepan.mp3"},"examples":[{"en":"Heat the oil and garlic in a large saucepan.","cn":"在大平底锅里把油和大蒜加热。"}],"oxford":{"phon":"ˈsɔːspən","pos":"noun","senses":[{"en":"a deep round metal pot with a lid (= cover) and one long handle or two short handles, used for cooking things over heat","cn":"（带盖，有一长柄或双耳的）深煮锅","ex":{"en":"a saucepan of boiling water","cn":"一锅开水"}}]}},"saunter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"闲逛;漫步","en":"If you saunter somewhere, you walk there in a slow, casual way.","ex":{"en":"We watched our fellow students saunter into the building","cn":"我们看着同学们悠闲地走进了大楼。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk in a slow and relaxed way, especially for pleasure","cn":""},{"en":"to walk in a slow and relaxed way, especially when you are going a short distance, or not going anywhere in particular","cn":""},{"en":"to walk in a slow and lazy way, often when you should be hurrying to do something","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To saunter is to stroll at a leisurely pace. The next time someone accuses you of dragging your feet and asks you to speed it up, calmly tell them that you’re perfecting your saunter ."}]},"collocations":{"phrases":["ADV. casually, slowly | along, back, in, out, over She sauntered in fifteen minutes late.","PREP. along, into, out of, through, etc. He sauntered casually through the door.","PHRASES come sauntering He came sauntering over to meet us."]},"media":{"uk":"media/ldoce/hwd/bre/f/saunter0205.mp3","us":"media/ldoce/hwd/ame/e/saunter.mp3"},"examples":[{"en":"He sauntered by, looking as if he had all the time in the world.","cn":"他悠闲地走过，彷佛时间对他来说是无穷无尽的。"},{"en":"This part of the route should be an easy saunter.","cn":"这段路想必好走。"}],"oxford":{"phon":"ˈsɔːntə(r)","pos":"noun","senses":[{"en":"a slow relaxed walk","cn":"散步；溜达；闲逛","ex":{"en":"This part of the route should be an easy saunter.","cn":"这段路想必好走。"}},{"en":"to walk in a slow relaxed way","cn":"悠闲地走；漫步；闲逛","ex":{"en":"He sauntered by, looking as if he had all the time in the world.","cn":"他悠闲地走过，仿佛时间对他来说是无穷无尽的。"},"pos":"verb"}]}},"sadden":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使悲哀;使悲伤;使伤心","en":"If something saddens you, it makes you feel sad.","ex":{"en":"The cruelty in the world saddens me incredibly.","cn":"人世间的残酷无情让我感到无比悲哀。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone feel sad and want to cry","cn":""},{"en":"if a situation or event saddens someone, it makes them feel sad, especially because they think that this type of situation or event should not happen","cn":""},{"en":"to make someone feel very sad or unhappy, especially so that they feel that only bad things happen and they cannot change the situation","cn":""}]},"collocations":{"phrases":["ADV. deeply, greatly I was deeply saddened by his death."]},"media":{"uk":"media/ldoce/hwd/bre/a/sadden0205.mp3","us":"media/ldoce/hwd/ame/2/sadden.mp3"},"examples":[{"en":"Fans were saddened to see the former champion play so badly.","cn":"看到以前的冠军表现如此差劲，球迷感到难过。"},{"en":"We were deeply saddened by the news of her death.","cn":"听到她的死讯，我们深感悲伤。"}],"oxford":{"phon":"ˈsædn","pos":"verb","senses":[{"en":"to make somebody sad","cn":"使悲伤；使伤心；使难过","ex":{"en":"We were deeply saddened by the news of her death.","cn":"听到她的死讯，我们深感悲伤。"}}]}},"saver":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"储蓄者;储户","en":"A saver is a person who regularly saves money by paying it into a bank account or a building society.","ex":{"en":"Low interest rates are bad news for savers.","cn":"低利率对于储蓄者来说是个坏消息。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who saves money in a bank 〔","cn":"银行的〕储蓄者﹐储户"}]},"collocations":{"phrases":["ADJ. existing Only children whose parents are existing savers may open an account. | small encouraging small savers to invest in UK companie","PREP. ~ with savers with the United Bank"]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdesaver.mp3","us":"media/ldoce/hwd/ame/4/laadsaver.mp3"},"examples":[{"en":"a money/time saver","cn":"省钱/省时的事物"},{"en":"Mutual funds have been attractive to small savers (= people who save small amounts of money ) .","cn":"共同基金对小额储户很有吸引力。"}],"oxford":{"phon":"ˈseɪvə(r)","pos":"noun","senses":[{"en":"a person who saves money and puts it in a bank, etc. for future use","cn":"储户；存户","ex":{"en":"The increase in interest rates is good news for savers.","cn":"利率上升对储户是个好消息。"}},{"en":"something that helps you spend less money or use less of the thing mentioned","cn":"有助于节省的事物","ex":{"en":"a money/time saver","cn":"省钱／省时的事物"}}]}},"salute":{"collins":{"senses":[{"pos":"VERB 动词","cn":"向…致意;向…致敬;向…行军礼","en":"If you salute someone, you greet them or show your respect with a formal sign. Soldiers usually salute officers by raising their right hand so that their fingers touch their forehead.","ex":{"en":"One of the company stepped out and saluted the General","cn":"人群中走出一人向将军敬礼。"}},{"pos":"VERB 动词","cn":"赞扬;颂扬","en":"To salute a person or their achievements means to publicly show or state your admiration for them.","ex":{"en":"I salute him for the leadership role that he is taking","cn":"我对他发挥的领导作用表示赞扬。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move your right hand to your head, especially in order to show respect to an officer in the army, navy etc （","cn":"向…）行军礼﹐（向…）致敬"},{"en":"to praise someone for the things they have achieved, especially publicly 〔","cn":"尤指公开地〕赞扬﹐颂扬"},{"en":"to greet someone in a polite way, especially by moving your hand or body 〔","cn":"尤用手或身体动作〕向…打招呼﹐向…致意"}]},"vocab":{"pos":"1 v n 2 v n","senses":[{"en":"A salute is a sign of respect. A soldier may salute senior officers by raising a hand to his or her head, or you may informally salute a neighbor with a tip of your hat."}]},"collocations":{"phrases":["ADV. smartly The captain stood to attention and saluted smartly.","PREP. with He saluted Pippa with a graceful bend of his head."]},"media":{"uk":"media/ldoce/hwd/bre/8/salute_v0205.mp3","us":"media/ldoce/hwd/ame/9/salute1.mp3"},"examples":[{"en":"The president saluted the courage of those who had fought for their country.","cn":"总统对那些为国战斗者的英勇精神表示敬意。"},{"en":"His first words were a salute to the people of South Africa.","cn":"他开口首先向南非人民致敬。"}],"oxford":{"phon":"səˈluːt","pos":"verb","senses":[{"en":"to touch the side of your head with the fingers of your right hand to show respect, especially in the armed forces","cn":"（尤指军队中）敬礼","g":"[intransitive, transitive]","ex":{"en":"The sergeant stood to attention and saluted.","cn":"中士立正敬礼。"}},{"en":"to show that you respect and admire somebody/something","cn":"致敬；表示敬意","g":"[transitive]","lab":"formal","ex":{"en":"The players saluted the fans before leaving the field.","cn":"球员在退场前向球迷致意。"}},{"en":"the action of raising your right hand to the side of your head as a sign of respect, especially between soldiers and officers","cn":"（尤指士兵和军官之间的）敬礼","g":"[countable]","ex":{"en":"He returned the salute as he passed the line of guards.","cn":"当他穿过警卫队时，他回敬了一个礼。"},"pos":"noun"},{"en":"a thing that you say or do to show that you respect and admire somebody/something or to welcome somebody","cn":"致敬；致意","g":"[countable, uncountable]","ex":{"en":"He raised his hat as a friendly salute.","cn":"他举帽亲切致意。"},"pos":"noun"},{"en":"an official occasion when guns are fired into the air to show respect for an important person","cn":"鸣礼炮；鸣炮致敬","g":"[countable]","ex":{"en":"a 21-gun salute","cn":"鸣炮 21 响的礼仪"},"pos":"noun"}]}},"sane":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"心智健全的;神志正常的","en":"Someone who is sane is able to think and behave normally and reasonably, and is not mentally ill.","ex":{"en":"He seemed perfectly sane","cn":"他似乎神志完全正常。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"清醒的;明智的;合情合理的","en":"If you refer to a sane person, action, or system, you mean one that you think is reasonable and sensible.","ex":{"en":"No sane person wishes to see conflict or casualties.","cn":"理智的人都不愿意看到冲突或伤亡。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not mentally ill, so that you are able to make sensible decisions and lead your life in a normal way","cn":""},{"en":"when you are mentally healthy","cn":""},{"en":"a legal expression meaning not mentally ill and able to be responsible for your decisions and actions","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A sane person doesn't have any screws loose — in other words, they're free of mental illness and in a reasonable state of mind."}]},"collocations":{"phrases":["VERBS be, seem | remain, stay | keep sb Having that little bit of time to myself is what keeps me sane.","ADV. eminently, very | completely, perfectly, quite, utterly She seems perfectly sane to me. | not entirely"]},"media":{"uk":"media/ldoce/hwd/bre/f/sane0205.mp3","us":"media/ldoce/hwd/ame/5/sane.mp3"},"examples":[{"en":"Being able to get out of the city at the weekend keeps me sane.","cn":"要不是能出城过过周末，我简直快憋疯了。"},{"en":"No sane person would do that.","cn":"没有一个神志正常的人会做那样的事。"}],"oxford":{"phon":"seɪn","pos":"adjective","senses":[{"en":"having a healthy mind; not mentally ill","cn":"精神健全的；神志正常的","ex":{"en":"No sane person would do that.","cn":"没有一个神志正常的人会做那样的事。"}},{"en":"sensible and reasonable","cn":"明智的；理智的；合乎情理的","ex":{"en":"the sane way to solve the problem","cn":"解决问题的明智方法"}}]}},"sanity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"心智健全;精神正常","en":"A person's sanity is their ability to think and behave normally and reasonably.","ex":{"en":"He and his wife finally had to move from their apartment just to preserve their sanity.","cn":"为了不致发疯，他和妻子最终只得从公寓中搬出。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"清醒;明智;通情达理","en":"If there is sanity in a situation or activity, there is a purpose and a regular pattern, rather than confusion and worry.","ex":{"en":"Rafsanjani has been considering various ways of introducing some sanity into the currency market.","cn":"拉夫桑贾尼一直考虑通过各种方式使货币市场趋于理性。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"not mentally ill, so that you are able to make sensible decisions and lead your life in a normal way","cn":""},{"en":"when you are mentally healthy","cn":""},{"en":"a legal expression meaning not mentally ill and able to be responsible for your decisions and actions","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Sanity is the opposite of insanity. When you have sanity , you're mentally healthy and not acting crazy."}]},"collocations":{"phrases":["VERB + SANITY doubt, question There were moments when he doubted his own sanity. | fear for I fear for her sanity if this continues much lon","SANITY + VERB return Stock market trading slowly settled down as sanity returned.","PREP. for your ~ Such a move is essential for the sanity of all concerned."]},"media":{"uk":"media/ldoce/hwd/bre/b/sanity0205.mp3","us":"media/ldoce/hwd/ame/0/sanity.mp3"},"examples":[{"en":"After a series of road accidents the police pleaded for sanity among drivers.","cn":"在发生一系列交通事故之后，警方提请驾驶人要审慎驾车。"},{"en":"His behaviour was so strange that I began to doubt his sanity.","cn":"他行为怪异，我有点怀疑他是否神智正常。"}],"oxford":{"phon":"ˈsænəti","pos":"noun","senses":[{"en":"the state of having a healthy mind","cn":"精神健全；神志正常","ex":{"en":"His behaviour was so strange that I began to question his sanity.","cn":"他行为怪异，我有点怀疑他是否神志正常。"}},{"en":"the state of being sensible and reasonable","cn":"明智；理智；通情达理","ex":{"en":"After a series of road accidents the police pleaded for sanity among drivers.","cn":"在发生一系列交通事故之后，警方提请驾驶员要审慎驾车。"}}]}},"sanitation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"公共卫生;环境卫生","en":"Sanitation is the process of keeping places clean and healthy, especially by providing a sewage system and a clean water supply.","ex":{"en":"...the hazards of contaminated water and poor sanitation.","cn":"水污染和恶劣卫生环境的危害"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the protection of public health by removing and treating waste, dirty water etc","cn":"公共卫生﹐环境卫生"}]},"vocab":{"pos":"n","senses":[{"en":"Sanitation has to do with making things clean, especially by sterilizing."}]},"collocations":{"phrases":["ADJ. inadequate, poor, primitive | better, improved, proper | public","SANITATION + NOUN system | project","PHRASES lack of sanitation the direct link between disease and lack of adequate sanitation"]},"media":{"uk":"media/ldoce/hwd/bre/a/sanitation0205.mp3","us":"media/ldoce/hwd/ame/7/sanitation.mp3"},"examples":[{"en":"disease resulting from poor sanitation","cn":"卫生条件差导致的疾病"},{"en":"Overcrowding and poor sanitation are common problems in prisons.","cn":"过度拥挤和卫生状况差是监狱里的普遍问题。"}],"oxford":{"phon":"ˌsænɪˈteɪʃn","pos":"noun","senses":[{"en":"the equipment and systems that keep places clean, especially by removing human waste","cn":"卫生设备；卫生设施体系","ex":{"en":"disease resulting from poor sanitation","cn":"卫生条件差导致的疾病"}}]}},"saturation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"饱和过程(或状态);饱和","en":"Saturation is the process or state that occurs when a place or thing is filled completely with people or things, so that no more can be added.","ex":{"en":"Reforms have led to the saturation of the market with goods","cn":"改革已经使得市场上商品饱和。"}},{"pos":"ADJ 形容词","cn":"(运动、活动)饱和的，全面的","en":"Saturation is used to describe a campaign or other activity that is carried out very thoroughly, so that nothing is missed.","ex":{"en":"The concept of saturation marketing makes perfect sense","cn":"饱和营销的概念是完全有道理的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when an event or person is given so much attention by newspapers, television etc that everyone has heard about it","cn":"饱和报道﹐铺天盖地的报道"},{"en":"a military attack in which a whole area is bombed","cn":"饱和轰炸﹐全面性轰炸"},{"en":"the degree to which something has been mixed into something else","cn":"饱和度"}]},"vocab":{"pos":"n","senses":[{"en":"Saturation means holding as much moisture as possible. When you water your houseplants, you may soak them until the soil around each plant reaches saturation ."}]},"collocations":{"phrases":["ADJ. market","VERB + SATURATION approach, be close to The company's sales are now close to saturation in many western countries. | reach","SATURATION + NOUN level, point Demand for the product has reached saturation point. | coverage television's saturation coverage of the World"]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41saturation.mp3","us":"media/ldoce/hwd/ame/4/saturation.mp3"},"examples":[{"en":"There was saturation coverage (= so much that it was impossible to avoid it or add to it) of the event by the media.","cn":"媒体对这一事件做了连篇累牍的报道。"},{"en":"a business beset by price wars and market saturation (= the fact that no new customers can be found)","cn":"一家受价格战和市场饱和困扰的企业"}],"oxford":{"phon":"ˌsætʃəˈreɪʃn","pos":"noun","senses":[{"en":"the state or process that happens when no more of something can be accepted or added because there is already too much of it or too many of them","cn":"饱和；饱和状态","lab":"often figurative","ex":{"en":"a business beset by price wars and market saturation (= the fact that no new customers can be found)","cn":"一家受价格战和市场饱和困扰的企业"}},{"en":"the degree to which something is absorbed into something else, expressed as a percentage of the greatest possible","cn":"饱和度","lab":"chemistry","ex":{"en":"Was dissolved oxygen in the water greater than 80% of saturation?","cn":"水中的溶解氧是否超过饱和度的 80%？"}}]}},"savage":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"凶恶的;残暴的;凶猛的;野的;未驯服的","en":"Someone or something that is savage is extremely cruel, violent, and uncontrolled.","ex":{"en":"This was a savage attack on a defenceless young girl.","cn":"这是对一个毫无自卫能力的年轻女孩的野蛮袭击。"}},{"pos":"N-COUNT 可数名词","cn":"野蛮人;未开化的人","en":"If you refer to people as savages, you dislike them because you think that they do not have an advanced society and are violent.","ex":{"en":"...their conviction that the area was a frozen desert peopled with uncouth savages.","cn":"他们深信该地区曾是严寒的沙漠并居住着未开化的野人"}},{"pos":"VERB 动词","cn":"(狗等)凶猛地攻击，撕咬","en":"If someone is savaged by a dog or other animal, the animal attacks them violently.","ex":{"en":"The animal then turned on him and he was savaged to death.","cn":"接着野兽突然袭击了他，最后把他咬死了。"}},{"pos":"VERB 动词","cn":"激烈批评;猛烈抨击","en":"If someone or something that they have done is savaged by another person, that person criticizes them severely.","ex":{"en":"The show had already been savaged by critics","cn":"这场演出已受到评论家们的激烈抨击。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"using force to hurt or kill people – used about people, crimes etc. Also used about films or books that contain a lot of violence","cn":""},{"en":"violent and dangerous, and seeming to enjoy hurting people for no reason","cn":""},{"en":"using force or violence, but not causing serious injury","cn":""}]},"vocab":{"pos":"adj n v","senses":[{"en":"A polar bear in a zoo might look like an adorable giant stuffed animal, but if you met a hungry one in its native environment, it would seem more savage — wild and fierce — than cute."}]},"collocations":{"phrases":["VERBS be, look, seem, sound | become","ADV. downright, really, very | increasingly The war became increasingly savage. | rather a rather savage dog"]},"media":{"uk":"media/ldoce/hwd/bre/7/savage_adj0205.mp3","us":"media/ldoce/hwd/ame/d/savage1.mp3"},"examples":[{"en":"She had been badly hurt in what police described as ‘a savage attack’.","cn":"她遭受袭击而身受重伤，警方称这是一次“野蛮的袭击”。"},{"en":"Her latest novel has been savaged by the critics.","cn":"她最近的一部小说受到评论家的猛烈批评。"}],"oxford":{"phon":"ˈsævɪdʒ","pos":"adjective","senses":[{"en":"aggressive and violent; causing great harm","cn":"凶恶的；凶残的；损害严重的","ex":{"en":"savage dogs","cn":"恶狗"}},{"en":"involving very strong criticism","cn":"猛烈抨击的","ex":{"en":"The article was a savage attack on the government's record.","cn":"文章对政府的所作所为进行了猛烈的抨击。"}},{"en":"an offensive way of referring to groups of people or customs that are considered to be simple and not highly developed","cn":"蒙昧的；未开化的；野蛮的","g":"[only before noun]","lab":"old-fashioned, taboo, offensive，，，，","ex":{"en":"a savage tribe","cn":"野蛮部落"}},{"en":"an offensive word for somebody who belongs to a people considered to be simple and not developed","cn":"野蛮人；未开化的人","lab":"old-fashioned, taboo, offensive，，，，","pos":"noun"},{"en":"a cruel and violent person","cn":"凶狠残暴的人","ex":{"en":"He described the attack as the work of savages.","cn":"他把这次袭击称为野蛮行径。"},"pos":"noun"},{"en":"to attack somebody violently, causing serious injury","cn":"凶狠地攻击（或伤害）；残害","ex":{"en":"She was savaged to death by a bear.","cn":"她遭熊袭击而丧命。"},"pos":"verb"},{"en":"to criticize somebody/something severely","cn":"猛烈批评；严厉抨击","lab":"formal","ex":{"en":"Her latest novel has been savaged by the critics.","cn":"她最近的一部小说受到评论家的猛烈批评。"},"pos":"verb"}]}},"saks":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a well-known New York department store, known especially for its clothes. Its full name is Saks Fifth Avenue.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/lpd_saks.mp3","us":"media/ldoce/hwd/ame/b/lpd_saks.mp3"}},"sacred":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"神圣的;上帝的;神的","en":"Something that is sacred is believed to be holy and to have a special connection with God.","ex":{"en":"The owl is sacred for many Californian Indian people.","cn":"对于很多加利福尼亚的印第安人而言，猫头鹰是圣物。"}},{"pos":"ADJ 形容词","cn":"宗教的;用于宗教仪式的","en":"Something connected with religion or used in religious ceremonies is described as sacred .","ex":{"en":"...sacred art.","cn":"宗教艺术"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可侵犯的;不容干涉的;不可变更的","en":"You can describe something as sacred when it is regarded as too important to be changed or interfered with.","ex":{"en":"My memories are sacred","cn":"我的记忆不容亵渎。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to religion","cn":""},{"en":"relating to matters of the human spirit, rather than the physical world","cn":""},{"en":"connected with God and religion, and therefore treated in a special way – used especially in the following phrases","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something sacred is holy, devoted to a religious ceremony, or simply worthy of awe and respect. Jerusalem is a sacred place for many religions, just as Fenway is a sacred place for Red Sox fans."}]},"collocations":{"phrases":["VERBS be | become | remain | consider sth, deem sth, hold sth, regard sth as Certain animals were regarded as sacred. the feeling that all l","ADV. absolutely | almost","PREP. to The place was sacred to the Celts."]},"media":{"uk":"media/ldoce/hwd/bre/5/sacred_las2_br.mp3","us":"media/ldoce/hwd/ame/a/sacred.mp3"},"examples":[{"en":"For journalists nothing is sacred (= they write about anything).","cn":"在记者眼里，没什么是不可诉诸笔端的。"},{"en":"Human life must always be sacred.","cn":"人的生命在任何时候都必须得到尊重。"}],"oxford":{"phon":"ˈseɪkrɪd","pos":"adjective","senses":[{"en":"connected with God or a god; considered to be holy","cn":"上帝的；神的；神圣的","ex":{"en":"a sacred image/shrine/temple","cn":"圣像；圣地；圣殿"}},{"en":"very important and treated with great respect; that must not be changed or challenged","cn":"很重要的；极受尊重的；不容更改（或置疑）的","ex":{"en":"Human life must always be sacred.","cn":"人的生命在任何时候都必须得到尊重。"}}]}},"sandal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"凉鞋","en":"Sandals are light shoes that you wear in warm weather, which have straps instead of a solid part over the top of your foot."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a light shoe that is fastened onto your foot by bands of leather or cloth, and is worn in warm weather","cn":"凉鞋"}]},"collocations":{"phrases":["ADJ. high-heeled | flat, low-heeled | open, open-toed | strappy","QUANT. pair","VERB + SANDAL kick off •"]},"media":{"img":["media/ldoce/img/sandals.jpg","media/thumb/sandal.jpg"],"uk":"media/ldoce/hwd/bre/9/sandal0205.mp3","us":"media/ldoce/hwd/ame/3/sandal.mp3"},"examples":[{"en":"a pair of sandals","cn":"一双凉鞋"}],"oxford":{"phon":"ˈsændl","pos":"noun","senses":[{"en":"a type of light open shoe that is worn in warm weather. The top part consists of leather bands that fasten the sole to your foot.","cn":"凉鞋"}]}}});
